    def get_translator_name(self) -> str:
        """Return the user-configured translator name, falling back to system username."""
        settings = self.load_general_settings()
        name = settings.get('translator_name', '').strip()
        if name:
            return name
        return os.environ.get('USERNAME', os.environ.get('USER', 'user'))

    # ─── Standalone SDLXLIFF import/export ────────────────────────────────────

    # ========================================================================
    # PHRASE (MEMSOURCE) MXLIFF IMPORT/EXPORT
    # ========================================================================

    # ────────────────────────────────────────────────────────────────────
    # Bilingual Re-importable Text (AI-friendly, Bracketed) — export + re-import
    # v1.10.231. Ports the Trados plugin's "[SEGMENT NNNN]" round-trip: a plain
    # text file (editable target lines) + a .svexport.json sidecar that maps the
    # edited file back to THIS open project. Called "Text" (not Markdown)
    # because the segment blocks rely on preserved line breaks. The method names
    # keep the historical "markdown" wording as an internal detail. See
    # modules/bilingual_markdown_handler.py for the format + diff engine.
    # ────────────────────────────────────────────────────────────────────
    def export_bilingual_markdown(self):
        """Export segments as AI-friendly Bracketed Text + .svexport.json sidecar.

        Round-trips back into the SAME open project via import_bilingual_markdown().
        """
        try:
            if not self.current_project or not self.current_project.segments:
                QMessageBox.warning(self, "No Project",
                                    "Please open a project with segments first.")
                return

            from modules.bilingual_markdown_handler import (
                MdExportSegment, build_markdown, build_sidecar, write_export,
            )
            from modules.statuses import STATUSES, get_status
            from datetime import datetime, timezone

            segments = self._segments_in_document_order()
            # Flush any pending grid edits into the segment objects first, so the
            # export matches exactly what's on screen.
            try:
                self._sync_grid_targets_to_segments(segments)
            except Exception:
                pass

            # ── Options dialog ──────────────────────────────────────────────
            dialog = QDialog(self)
            dialog.setWindowTitle(self.tr("Export Bilingual Text (AI-friendly)"))
            dialog.setMinimumWidth(480)
            d_layout = QVBoxLayout(dialog)

            info = QLabel(
                "Export a bilingual text file in the AI-friendly "
                "<b>[SEGMENT NNNN]</b> format, with a <code>.svexport.json</code> "
                "sidecar written alongside it.<br><br>"
                "Edit the target lines in any text editor or with an LLM, then "
                "re-import via <b>Project → Import → 🔁 Supervertaler Re-importable → "
                "Bilingual Text (AI-friendly) - Update Project…</b> to update this project."
            )
            info.setTextFormat(Qt.TextFormat.RichText)
            info.setWordWrap(True)
            d_layout.addWidget(info)
            d_layout.addSpacing(8)

            include_locked_cb = CheckmarkCheckBox(self.tr("Include locked segments"))
            include_locked_cb.setChecked(True)
            d_layout.addWidget(include_locked_cb)

            # Status filter — only the statuses actually present in the project.
            present_keys = []
            seen = set()
            for s in segments:
                k = get_status(s.status).key
                if k not in seen:
                    seen.add(k)
                    present_keys.append(k)
            status_group = QGroupBox(self.tr("Include statuses"))
            sg_layout = QVBoxLayout(status_group)
            status_cbs = {}
            for k in present_keys:
                lbl = STATUSES[k].label if k in STATUSES else k
                cb = CheckmarkCheckBox(lbl)
                cb.setChecked(True)
                sg_layout.addWidget(cb)
                status_cbs[k] = cb
            d_layout.addWidget(status_group)

            buttons = QDialogButtonBox(
                QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel)
            buttons.button(QDialogButtonBox.StandardButton.Ok).setText(self.tr("Save to File..."))
            # Issue #248: skip the file entirely – copy the text for an AI chat
            # and bring the reply back with Update from Pasted Text.
            copy_mode = {"on": False}
            copy_btn = buttons.addButton(self.tr("📋 Copy to Clipboard"),
                                         QDialogButtonBox.ButtonRole.AcceptRole)
            copy_btn.setToolTip(self.tr(
                "Copy the text instead of saving a file. Paste it into an AI chat, "
                "then bring the edited reply back with Update from Pasted Text."))
            copy_btn.clicked.connect(lambda: copy_mode.update(on=True))
            buttons.accepted.connect(dialog.accept)
            buttons.rejected.connect(dialog.reject)
            d_layout.addWidget(buttons)

            if dialog.exec() != QDialog.DialogCode.Accepted:
                return
            to_clipboard = copy_mode["on"]

            include_locked = include_locked_cb.isChecked()
            selected_keys = {k for k, cb in status_cbs.items() if cb.isChecked()}
            status_filter = None if selected_keys == set(present_keys) else selected_keys

            # ── Build the export list ──────────────────────────────────────
            export_segs = []
            number = 0
            for seg in segments:
                key = get_status(seg.status).key
                if not include_locked and getattr(seg, 'locked', False):
                    continue
                if status_filter is not None and key not in status_filter:
                    continue
                number += 1
                label = STATUSES[key].label if key in STATUSES else key
                export_segs.append(MdExportSegment(
                    number=number,
                    segment_id=seg.id,
                    source=seg.source or "",
                    target=seg.target or "",
                    status_key=key,
                    status_label=label,
                    locked=bool(getattr(seg, 'locked', False)),
                    file_name=getattr(seg, 'file_name', '') or "",
                    comment=getattr(seg, 'notes', '') or "",
                ))

            if not export_segs:
                QMessageBox.warning(self, "No Segments",
                                    "No segments match the selected options.")
                return

            # ── Save path ──────────────────────────────────────────────────
            file_path = ""
            if not to_clipboard:
                default_name = (self.current_project.name or "project").replace(" ", "_") + "_bilingual.txt"
                file_path, _ = QFileDialog.getSaveFileName(
                    self, "Export Bilingual Text", default_name,
                    "Text Files (*.txt);;All Files (*.*)")
                if not file_path:
                    return
                if not file_path.lower().endswith('.txt'):
                    file_path += '.txt'

            src_disp = self.current_project.source_lang or "Source"
            tgt_disp = self.current_project.target_lang or "Target"

            # A representative source file name for the header/sidecar.
            source_file_name = ""
            for s in export_segs:
                if s.file_name:
                    source_file_name = s.file_name
                    break
            if not source_file_name:
                source_file_name = self.current_project.name or ""

            multi_file = len({s.file_name for s in export_segs if s.file_name}) > 1

            # The workflow statuses a proofreader/LLM may set (the auto-assigned
            # TM/MT match statuses aren't meant to be set by hand).
            _status_choice_keys = ["not_started", "draft", "confirmed",
                                   "proofread", "approved", "rejected"]
            status_choices = [STATUSES[k].label for k in _status_choice_keys
                              if k in STATUSES]

            md_text = build_markdown(
                export_segs,
                project_name=self.current_project.name or "Untitled",
                source_file_name=source_file_name,
                source_lang_display=src_disp,
                target_lang_display=tgt_disp,
                tool_version=__version__,
                multi_file=multi_file,
                status_choices=status_choices,
            )
            sidecar = build_sidecar(
                export_segs,
                project_name=self.current_project.name or "Untitled",
                source_file_name=source_file_name,
                source_language=src_disp,
                target_language=tgt_disp,
                tool_version=__version__,
                export_file_path=file_path,
                timestamp_utc=datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
            )
            # Remembered for this session so Update from Pasted Text can map the
            # AI's reply back exactly, even where a source occurs more than once.
            self._bilingual_text_session_sidecar = (id(self.current_project), sidecar)

            if to_clipboard:
                QApplication.clipboard().setText(md_text)
                paste_key = format_shortcut_for_display(
                    self.shortcut_manager.get_shortcut("file_update_from_pasted_text") or "Ctrl+Shift+V")
                self.log(f"✓ Copied {len(export_segs)} segments to the clipboard as bilingual text")
                QMessageBox.information(
                    self, "Copied to Clipboard",
                    f"Copied {len(export_segs)} segment(s) to the clipboard.\n\n"
                    "Paste them into your AI chat. When you have the edited reply, "
                    "copy it and press " + paste_key + " (Project → Import → "
                    "🔁 Supervertaler Re-importable → Bilingual Text (AI-friendly) - "
                    "Update from Pasted Text…) to update this project.")
                return

            side_path = write_export(file_path, md_text, sidecar)

            self.log(f"✓ Exported {len(export_segs)} segments to bilingual text: "
                     f"{os.path.basename(file_path)} (+ sidecar)")
            QMessageBox.information(
                self, "Export Complete",
                f"Exported {len(export_segs)} segment(s) to:\n{os.path.basename(file_path)}\n\n"
                f"Sidecar: {os.path.basename(side_path)}\n\n"
                "Edit the target lines, then re-import via Project → Import → "
                "🔁 Supervertaler Re-importable → Bilingual Text (AI-friendly) - "
                "Update Project… to update this project.")

        except Exception as e:
            QMessageBox.critical(self, "Export Error",
                                 f"Failed to export bilingual text:\n\n{str(e)}")
            self.log(f"✗ Bilingual text export failed: {str(e)}")
            import traceback
            traceback.print_exc()
    
    # ========================================================================
    # GRID MANAGEMENT
    # ========================================================================
    
    # ---------------------------------------------------------------------
    # Page-aware grid loading (v1.10.147 — based on Hans Lenting's
    # "Simpelvertaler" fork). Instead of constructing ~1200 full QTextEdit
    # widgets up-front on project open, only build them for rows on the
    # current page; off-page rows get a cheap QTableWidgetItem placeholder
    # and the heavy widgets are installed lazily by the pagination handler
    # when they become visible. Major initial-load speedup on large
    # SDLXLIFF projects; scrolling/typing behaviour is unchanged.
    # ---------------------------------------------------------------------

    def _compute_initial_visible_rows(self, total: int) -> set:
        """Return the set of row indices that should get full editor widgets
        on initial grid load (current page only).

        Part of the page-aware grid loading optimisation in v1.10.147 (based
        on Hans Lenting's Simpelvertaler fork). Off-page rows get a cheap
        QTableWidgetItem placeholder and are populated lazily by the
        pagination handler when they become visible.
        """
        filter_allowlist = getattr(self, '_active_text_filter_rows', None)
        if filter_allowlist is not None:
            return set(filter_allowlist)
        page_size = getattr(self, 'grid_page_size', 50)
        if not isinstance(page_size, int) or page_size <= 0 or page_size >= 999999:
            # "All" mode (or unset) — populate every row.
            return set(range(total))
        current_page = getattr(self, 'grid_current_page', 0)
        start_row = current_page * page_size
        end_row = min(start_row + page_size, total)
        return set(range(start_row, end_row))

    def _populate_single_row(self, row, segment):
        """Install full source/target editor widgets and metadata for one row
        (see _populate_single_row_widgets); each editor's stylesheet is applied
        once, when the row is complete."""
        with _GridStyleBatch():
            self._populate_single_row_widgets(row, segment)

    def _populate_single_row_widgets(self, row, segment):
        """Install full source/target editor widgets and metadata for one row.

        Extracted from the per-row body of load_segments_to_grid as part of
        the page-aware grid loading optimisation in v1.10.147 (based on
        Hans Lenting's Simpelvertaler fork). Called once per row at grid
        load for rows on the current page, and called lazily by the
        pagination handler when off-page rows become visible. Tracks which
        rows have widgets via self._populated_rows.
        """
        if not hasattr(self, '_populated_rows'):
            self._populated_rows = set()
        # The pre-pass in load_segments_to_grid stashes the computed list
        # numbers on self; use them here for both eager and lazy population.
        list_numbers = getattr(self, '_list_numbers', {})

        # Clear any previous cell widgets
        self.table.removeCellWidget(row, 2)  # Source
        self.table.removeCellWidget(row, 3)  # Target
        self.table.removeCellWidget(row, 4)  # Match
        self.table.removeCellWidget(row, 5)  # Status
        
        # ID - Segment number (black in light themes, theme text color in dark themes)
        id_item = QTableWidgetItem(str(segment.id))
        id_item.setFlags(id_item.flags() & ~Qt.ItemFlag.ItemIsEditable)  # Read-only
        id_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
        # Black for light themes, theme text color for dark themes
        theme = self.theme_manager.current_theme
        segment_num_color = "black" if theme.name in ["Light (Default)", "Soft Gray", "Warm Cream", "Sepia", "High Contrast"] else theme.text
        id_item.setForeground(QColor(segment_num_color))
        id_item.setBackground(QColor())  # Default background from theme
        # Smaller font for segment numbers
        seg_num_font = QFont(self.default_font_family, max(9, self.default_font_size - 1))
        id_item.setFont(seg_num_font)
        self.table.setItem(row, 0, id_item)
        
        # Type - show segment type based on style and content
        # Determine type display from style attribute and segment type
        style = getattr(segment, 'style', 'Normal')
        
        # Check for list items - use stored list_type/list_number if available
        list_type = getattr(segment, 'list_type', '')
        list_number_stored = getattr(segment, 'list_number', None)
        
        # Use pre-calculated list number from our loop above
        list_number_calculated = list_numbers.get(row, None)
        
        # Fallback: detect from source text if list_type not set
        source_text = segment.source.strip()
        is_list_item = bool(list_type) or (
            source_text.startswith('<li-o>') or  # Tagged ordered list item
            source_text.startswith('<li-b>') or  # Tagged bullet list item
            source_text.startswith('<li>') or    # Legacy list tag
            source_text.lstrip().startswith(('• ', '- ', '* ', '· ')) or
            (len(source_text) > 2 and source_text[0].isdigit() and source_text[1:3] in ('. ', ') '))
        )
        
        # Okapi sub-document category (comment/header/footer/property/notes)
        # takes precedence over style-based labelling, so the user can see at
        # a glance which segments are not ordinary body text.
        category = getattr(segment, 'category', '') or ''
        _CATEGORY_LABELS = {
            'comment':  ('Cmt',  'Comment'),
            'header':   ('Hdr',  'Header'),
            'footer':   ('Ftr',  'Footer'),
            'property': ('Prop', 'Document property'),
            'notes':    ('Note', 'Speaker notes'),
        }

        # Determine type display
        if category in _CATEGORY_LABELS:
            type_display = _CATEGORY_LABELS[category][0]
        elif 'Title' in style:
            type_display = "Title"
        elif 'Heading 1' in style or 'Heading1' in style:
            type_display = "H1"
        elif 'Heading 2' in style or 'Heading2' in style:
            type_display = "H2"
        elif 'Heading 3' in style or 'Heading3' in style:
            type_display = "H3"
        elif 'Heading 4' in style or 'Heading4' in style:
            type_display = "H4"
        elif 'Subtitle' in style:
            type_display = "Sub"
        elif is_list_item:
            # Show list number for numbered lists, bullet for unordered
            # Check for <li-b> tag first (explicit bullet)
            if '<li-b>' in source_text:
                type_display = "•"
            # Check for bullet patterns in text
            elif source_text.lstrip().startswith(('• ', '- ', '* ', '· ')):
                type_display = "•"
            elif list_type == "bullet":
                type_display = "•"
            elif list_number_stored is not None:
                type_display = f"#{list_number_stored}"
            elif list_number_calculated is not None:
                type_display = f"#{list_number_calculated}"
            elif '<li-o>' in source_text or '<li>' in source_text:
                # Ordered list - use calculated number or show #?
                type_display = f"#{list_numbers.get(row, '?')}"
            elif list_type == "numbered":
                type_display = "#?"
            else:
                # Fallback: check for number at start of text
                import re
                num_match = re.match(r'^(\d+)[.)\s]', source_text)
                if num_match:
                    type_display = f"#{num_match.group(1)}"
                elif '<li-o>' in source_text:
                    # Has <li-o> but no number - numbered list
                    type_display = "#?"
                else:
                    type_display = "li"
        elif segment.type and segment.type != "para":
            # Handle # type specially - only show #N for actual numbered items
            if segment.type == "#":
                # Plain "#" means continuation text within a list, show as paragraph
                type_display = "¶"
            elif segment.type.startswith("#") and len(segment.type) > 1:
                # Has a number like "#1", "#2" - keep it
                type_display = segment.type
            else:
                type_display = segment.type.upper()
        else:
            type_display = "¶"  # Paragraph symbol
        
        type_item = QTableWidgetItem(type_display)
        type_item.setFlags(type_item.flags() & ~Qt.ItemFlag.ItemIsEditable)  # Read-only
        type_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)

        # Color-code by type for better visibility
        if category in _CATEGORY_LABELS:
            # Non-body content: comments stand out in magenta; headers/
            # footers/properties/notes share a purple. Tooltip spells it out.
            type_item.setToolTip(_CATEGORY_LABELS[category][1])
            type_item.setForeground(
                QColor("#C2185B") if category == 'comment' else QColor("#7B1FA2"))
        elif type_display in ("H1", "H2", "H3", "H4", "Title"):
            type_item.setForeground(QColor("#1976D2"))  # Blue for headings (works in both themes)
        elif type_display.startswith("#") or type_display in ("•", "li"):
            type_item.setForeground(QColor("#388E3C"))  # Green for list items (works in both themes)

        # Slightly smaller font for type symbols (kept in sync with apply_font_to_grid).
        # The ¶ paragraph mark renders heavier than the text labels, so shave an
        # extra point off it specifically.
        _type_delta = 2 if type_display == "¶" else 1
        type_font = QFont(self.default_font_family, max(6, self.default_font_size - _type_delta))
        type_item.setFont(type_font)

        self.table.setItem(row, 1, type_item)
        
        # Source - Use read-only QTextEdit widget for easy text selection
        # Strip outer wrapping tags if setting is enabled (display only, data unchanged)
        source_for_display = segment.source
        stripped_source_tag = None
        if self.hide_outer_wrapping_tags:
            stripped, stripped_source_tag = strip_outer_wrapping_tags(segment.source)
            source_for_display = stripped
        # Apply compact tag shortening if in compact mode
        # Build tag_map from source so target uses same numbering
        _compact_tag_map = None
        if getattr(self, 'tag_view_mode', 'tags') == 'compact':
            _compact_tag_map = {}
            source_for_display = compact_tags(source_for_display, _compact_tag_map)
        # Apply invisible character replacements for display only
        source_display_text = self.apply_invisible_replacements(source_for_display)
        # v1.10.229: Honour the "Allow Replace in Source Text" setting at cell
        # creation time. The cell widget (this editor) pre-empts the table
        # delegate's createEditor, so the delegate's source-edit branch never
        # ran — that's why the warning banner appeared but the cell stayed
        # locked. Source remains read-only for locked segments regardless.
        _allow_src_edit = bool(getattr(self, 'allow_replace_in_source', False)) \
                          and not getattr(segment, 'locked', False)
        source_editor = ReadOnlyGridTextEditor(
            source_display_text, self.table, row, allow_edit=_allow_src_edit
        )
        # Stash the compact tag map + stripped wrapping tag on the source
        # editor so the textChanged handler can reverse the display-only
        # transforms before writing back to segment.source.
        source_editor._compact_tag_map = _compact_tag_map
        source_editor._stripped_outer_tag = stripped_source_tag
        # Track segment locked state on the widget so update_grid_delegate()
        # can refresh editability without re-deriving it from row indices
        # (which don't survive filters / sorts).
        source_editor._segment_locked = bool(getattr(segment, 'locked', False))

        # Initialize empty termbase matches (will be populated lazily on segment selection or by background worker)
        source_editor.termbase_matches = {}

        # Set font to match grid – both setFont (so editor knows its
        # logical font) AND apply_grid_font_size (so the size lives in
        # the widget's own stylesheet and wins over ThemeManager's
        # app-level QTextEdit rule at non-100% UI scale).
        font = QFont(self.default_font_family, self.default_font_size)
        source_editor.setFont(font)
        source_editor.apply_grid_font_size(self.default_font_size)

        # Set as cell widget (allows easy text selection)
        self.table.setCellWidget(row, 2, source_editor)

        # Also set a placeholder item for row height calculation
        source_item = QTableWidgetItem()
        source_item.setFlags(Qt.ItemFlag.NoItemFlags)  # No interaction
        self.table.setItem(row, 2, source_item)

        # v1.10.229: Wire up the source textChanged handler unconditionally;
        # it gates on self.allow_replace_in_source AND the editor's
        # allow_source_edit at fire time, so it's a no-op when the setting is
        # off. Connecting it always means toggling the setting at runtime via
        # set_source_editable() immediately picks up edits without rebuilding
        # the grid.
        source_editor.textChanged.connect(
            self._make_source_changed_handler(segment.id, source_editor)
        )

        # Target - Use editable QTextEdit widget for easy text selection and editing
        # Strip outer wrapping tags if enabled (will be auto-restored when saving)
        target_for_display = segment.target
        stripped_target_tag = None
        if self.hide_outer_wrapping_tags:
            stripped, stripped_target_tag = strip_outer_wrapping_tags(segment.target)
            target_for_display = stripped
            # Store stripped tag on segment for restore during save
            # Use source tag as reference (target should match source structure)
            segment._stripped_outer_tag = stripped_source_tag or stripped_target_tag

        # Apply compact tag shortening to target (display only – reversed before saving)
        if _compact_tag_map is not None:
            target_for_display = compact_tags(target_for_display, _compact_tag_map)
        # Apply invisible character replacements for display (will be reversed when saving)
        target_display_text = self.apply_invisible_replacements(target_for_display)
        target_editor = EditableGridTextEditor(target_display_text, self.table, row, self.table)
        target_editor.setFont(font)
        target_editor.apply_grid_font_size(self.default_font_size)
        # Store stripped tag on editor for auto-restore
        target_editor._stripped_outer_tag = stripped_source_tag or stripped_target_tag
        # Store compact tag map for reverse-expanding on save
        target_editor._compact_tag_map = _compact_tag_map

        # Make locked segments read-only (included for context only)
        if getattr(segment, 'locked', False):
            target_editor.setReadOnly(True)

        # Connect text changes to update segment
        # Use a factory function to create a proper closure that captures the segment ID
        def make_target_changed_handler(segment_id, editor_widget):
            # Create debounce timer for expensive operations
            debounce_timer = None
            
            def on_target_text_changed():
                nonlocal debounce_timer
                # In WYSIWYG view the cell shows rendered bold/italic/etc., so
                # toPlainText() would silently drop those tags. Rebuild them
                # from the cell's actual formatting instead; fall back to plain
                # text on any error so an edit is never lost. Tags/Compact view
                # already show the literal tags, so they stay on toPlainText().
                if getattr(self, 'tag_view_mode', 'tags') == 'wysiwyg':
                    try:
                        new_text = self._wysiwyg_document_to_tagged_text(editor_widget)
                    except Exception as _e:
                        new_text = editor_widget.toPlainText()
                        if getattr(self, 'debug_mode_enabled', False):
                            self.log(f"⚠ WYSIWYG tag rebuild failed, kept plain text: {_e}")
                else:
                    new_text = editor_widget.toPlainText()

                # Reverse compact tag placeholders before saving
                compact_map = getattr(editor_widget, '_compact_tag_map', None)
                if compact_map:
                    new_text = expand_compact_tags(new_text, compact_map)

                # Reverse invisible character replacements before saving
                new_text = self.reverse_invisible_replacements(new_text)

                # Auto-restore stripped outer wrapping tags if they were hidden
                stripped_tag = getattr(editor_widget, '_stripped_outer_tag', None)
                if stripped_tag and self.hide_outer_wrapping_tags:
                    # Only re-add if the text doesn't already have the tag
                    if not new_text.strip().startswith(f'<{stripped_tag}'):
                        new_text = f'<{stripped_tag}>{new_text}</{stripped_tag}>'

                # DEBUG: Log EVERY call to catch the culprit (only in debug mode)
                if self.debug_mode_enabled:
                    self.log(f"🔔 textChanged FIRED: segment_id={segment_id}, new_text='{new_text[:20] if new_text else 'EMPTY'}...'")

                # Mark that we've seen the first textChanged on this editor, but
                # do NOT swallow it. We used to return here unconditionally to
                # drop Qt's spurious queued event after a grid-load setPlainText
                # — but that also ate a *genuine* first edit that arrives as a
                # single event, most visibly **clearing** a cell: the empty
                # value never reached segment.target, so the old translation
                # survived save + reload (and kept showing in the Preview).
                # The idempotent guard below (new_text == old_target → return)
                # already absorbs the spurious event (it re-delivers unchanged
                # text), so a real change must be allowed through even when it's
                # the first one seen.
                editor_widget._initial_load_complete = True

                if self._suppress_target_change_handlers:
                    if self.debug_mode_enabled:
                        self.log(f"🔔 textChanged SUPPRESSED for segment {segment_id}")
                    return
                
                # CRITICAL: Find segment by ID, not by row index!
                # Row indices can change, but segment IDs are stable
                target_segment = next((seg for seg in self.current_project.segments if seg.id == segment_id), None)
                if not target_segment:
                    return
                
                # Capture old values for undo
                old_target = target_segment.target
                old_status = target_segment.status

                # Idempotent guard (v1.10.143): if the fully-cleaned text already
                # equals what's stored on the segment, this textChanged is a
                # spurious/programmatic event — Qt delivers queued document-change
                # events after our own blockSignals()+setPlainText() display
                # re-render (below) and at grid load — never a genuine user edit,
                # which always changes the text. Returning here keeps
                # segment.target reliably in sync on every real keystroke.
                # (Previously the re-render reset _initial_load_complete=False,
                # which could make the NEXT genuine edit be dropped, leaving a
                # stale segment.target → stale export + stale TM until a
                # re-confirm. That reset has been removed below.)
                if new_text == old_target:
                    return

                # Genuine user edit: from now on this cell keeps its own undo
                # history (so Ctrl+Z undoes typing); focusInEvent will no longer
                # clear it. See EditableGridTextEditor.focusInEvent.
                editor_widget._user_has_edited = True

                # Update the target text
                if self.debug_mode_enabled:
                    self.log(f"📝 BEFORE update: seg {segment_id} target='{target_segment.target[:30] if target_segment.target else 'EMPTY'}...', status={target_segment.status}, obj_id={id(target_segment)}")
                target_segment.target = new_text

                # Live-update the Document Preview (debounced, no-op when the
                # Preview tab is hidden) so the rendered text tracks edits and
                # flips source→translation as you type / clears back to source.
                self._schedule_preview_refresh()

                # If invisible markers are active, re-apply them so the widget display
                # stays in sync (e.g. ↵ after Shift+Enter when Show Invisibles is on).
                # In compact mode, use compact text for display (not the expanded save text)
                if hasattr(self, 'invisible_display_settings') and any(self.invisible_display_settings.values()):
                    display_source = new_text
                    compact_map = getattr(editor_widget, '_compact_tag_map', None)
                    if compact_map:
                        display_source = compact_tags(display_source, compact_map)
                    display_text = self.apply_invisible_replacements(display_source)
                    if display_text != editor_widget.toPlainText():
                        # Cursor position in the clean (marker-free) new_text.
                        # The widget currently shows the old display text; we need to
                        # map the cursor to its position in new_text first.
                        cur = editor_widget.textCursor()
                        old_display_pos = cur.position()
                        old_display = editor_widget.toPlainText()
                        # Convert old_display_pos → clean-text position by stripping
                        # markers that appear before cursor in the OLD display text.
                        old_before_cursor = old_display[:old_display_pos]
                        clean_pos = len(self.reverse_invisible_replacements(old_before_cursor))
                        # Now map clean_pos → new display_text position.
                        # apply_invisible_replacements inserts markers before each
                        # invisible char; count them in the display text up to clean_pos.
                        new_display_before = self.apply_invisible_replacements(display_source[:clean_pos])
                        new_pos = min(len(new_display_before), len(display_text))
                        editor_widget.blockSignals(True)
                        editor_widget.setPlainText(display_text)
                        cur.setPosition(new_pos)
                        editor_widget.setTextCursor(cur)
                        # v1.10.143: do NOT reset _initial_load_complete here.
                        # The queued spurious textChanged this setPlainText may
                        # emit is now harmlessly absorbed by the idempotent guard
                        # above (new_text == segment.target), so we no longer risk
                        # swallowing the user's next real keystroke.
                        editor_widget.blockSignals(False)

                # Reset 'confirmed' status to 'draft' when user edits the segment
                # This prevents auto-saving to TM until user re-confirms the edit
                new_status = old_status
                if old_status == 'confirmed' and new_text != old_target:
                    from PyQt6.QtCore import QTimer as QTimerLocal
                    new_status = 'draft'
                    target_segment.status = new_status
                    if self.debug_mode_enabled:
                        self.log(f"📝 Status reset: confirmed → draft (segment edited)")
                    # Refresh the status icon in the grid (debounced to avoid UI lag)
                    QTimerLocal.singleShot(0, lambda sid=segment_id: self._refresh_segment_status_by_id(sid))
                
                if self.debug_mode_enabled:
                    self.log(f"📝 AFTER update: seg {segment_id} target='{target_segment.target[:30] if target_segment.target else 'EMPTY'}...', status={target_segment.status}, obj_id={id(target_segment)}")
                
                # Record undo state with any status change
                self.record_undo_state(segment_id, old_target, new_text, old_status, new_status)
                
                # Mark project as modified
                self.project_modified = True
                
                # DEBOUNCED: Expensive UI/DB operations (only after user stops typing)
                # Cancel previous timer
                if debounce_timer:
                    debounce_timer.stop()
                
                # Schedule expensive operations after 500ms of inactivity
                from PyQt6.QtCore import QTimer
                debounce_timer = QTimer()
                debounce_timer.setSingleShot(True)
                # CRITICAL: Use default parameter to capture new_text BY VALUE, not by reference
                # This prevents the closure from capturing a variable that changes later
                debounce_timer.timeout.connect(lambda text=new_text: self._handle_target_text_debounced_by_id(
                    segment_id, text
                ))
                debounce_timer.start(1000)  # 1000ms delay (increased for better responsiveness)
                    
            return on_target_text_changed
        
        # Set as cell widget FIRST (before connecting signals)
        self.table.setCellWidget(row, 3, target_editor)
        
        # Also set a placeholder item for row height calculation
        target_item = QTableWidgetItem()
        target_item.setFlags(Qt.ItemFlag.NoItemFlags)  # No interaction
        self.table.setItem(row, 3, target_item)
        
        # CRITICAL: Connect textChanged AFTER widget is in table and setText is done
        # This prevents programmatic setText from triggering TM saves during grid reload
        target_editor.textChanged.connect(make_target_changed_handler(segment.id, target_editor))
        
        # DO NOT unblock signals here - they stay blocked until end of load_segments_to_grid

        # Pre-populate status cell item so gridlines render before widget assignment
        status_placeholder = QTableWidgetItem()
        status_placeholder.setFlags(Qt.ItemFlag.NoItemFlags)
        status_placeholder.setBackground(QColor(get_status(segment.status).color))
        self.table.setItem(row, 4, status_placeholder)

        # Status column (icon + match + comment)
        self._update_status_cell(row, segment)
        
        # Apply alternating row colors to source and target widgets
        self._apply_row_color(row, source_editor, target_editor)

        # File boundary separator for multi-file projects
        if getattr(self.current_project, 'is_multifile', False) and row > 0:
            prev_file_id = getattr(self.current_project.segments[row - 1], 'file_id', None)
            curr_file_id = getattr(segment, 'file_id', None)
            if curr_file_id is not None and prev_file_id is not None and curr_file_id != prev_file_id:
                source_editor.set_file_boundary(True)
                target_editor.set_file_boundary(True)
                # Re-apply row color so the border-top takes effect in the stylesheet
                self._apply_row_color(row, source_editor, target_editor)

        self._populated_rows.add(row)


    def load_segments_to_grid(self, progress_callback=None):
        """Load segments into the grid with termbase highlighting.

        progress_callback: optional callable(rows_done, total_rows). Called every
        ~25 rows during the build loop so callers can update a progress dialog
        and pump the Qt event loop, keeping the UI responsive on large imports.
        """
        self.log(f"🔄🔄🔄 load_segments_to_grid CALLED - this will RELOAD grid from segment data!")

        # Ensure original segment order is stored (for Document Order sort)
        if self.current_project and not hasattr(self, '_original_segment_order'):
            self._original_segment_order = self.current_project.segments.copy()

        # Clear row color settings cache to ensure fresh settings are loaded
        if hasattr(self, '_row_color_settings_cached'):
            delattr(self, '_row_color_settings_cached')
        
        # DEBUG: Log segment data BEFORE loading to grid
        if self.current_project and self.current_project.segments:
            self.log(f"🔄 BEFORE LOAD: First 7 segments:")
            for seg in self.current_project.segments[:7]:
                self.log(f"🔄   Seg {seg.id} (obj {id(seg)}): target='{seg.target[:30] if seg.target else 'EMPTY'}...', len={len(seg.target)}, status={seg.status}")
        
        if not self.current_project or not self.current_project.segments:
            self.clear_grid()
            return

        # Decide the page size for a newly-opened project (All, or paged for
        # very large docs). Runs once per project; no-op on re-renders.
        self._maybe_auto_set_page_size()

        self.table.setRowCount(len(self.current_project.segments))

        previous_suppression = self._suppress_target_change_handlers
        self._suppress_target_change_handlers = True
        
        # Pre-calculate list numbers for numbered lists
        # Track consecutive <li-o> or <li> items and assign numbers
        list_counter = 0
        last_was_list = False
        list_numbers = {}  # {segment_index: list_number}
        
        for idx, segment in enumerate(self.current_project.segments):
            source_text = segment.source.strip()
            # Support both new tags (<li-o>, <li-b>) and legacy <li> tag
            is_list_item = source_text.startswith('<li-o>') or source_text.startswith('<li-b>') or source_text.startswith('<li>')
            # <li-o> is ordered, <li> (legacy) is treated as ordered for numbering
            is_ordered = source_text.startswith('<li-o>') or (source_text.startswith('<li>') and not source_text.startswith('<li-b>'))
            
            # Check if it's a numbered list item (vs bullet)
            # If text inside <li-o> or <li> starts with a number pattern, extract it
            # Otherwise, if it's part of a consecutive list sequence, count it
            if is_list_item and is_ordered:
                import re
                # Check for number at start: <li-o>1. or <li>1. or <li-o>2) etc
                num_match = re.match(r'^<li(?:-o)?>\s*(\d+)[.)\s]', source_text)
                if num_match:
                    # Has explicit number in text
                    list_numbers[idx] = int(num_match.group(1))
                    list_counter = int(num_match.group(1))
                    last_was_list = True
                elif last_was_list:
                    # Continue numbering from previous
                    list_counter += 1
                    list_numbers[idx] = list_counter
                else:
                    # First item, start at 1
                    list_counter = 1
                    list_numbers[idx] = list_counter
                    last_was_list = True
            else:
                # Not a list item, reset counter
                last_was_list = False
                list_counter = 0

        try:
            _total_rows = len(self.current_project.segments)
            # v1.10.147: stash list_numbers on self so the lazy
            # populate path (pagination) can read them, and decide which
            # rows get full widgets right now vs cheap placeholders.
            self._list_numbers = list_numbers
            self._populated_rows = set()
            _initial_visible = self._compute_initial_visible_rows(_total_rows)

            for row, segment in enumerate(self.current_project.segments):
                # Yield to the Qt event loop every ~25 rows so the window
                # repaints and the OS doesn't mark it "Not Responding".
                if progress_callback is not None and row % 25 == 0:
                    try:
                        progress_callback(row, _total_rows)
                    except Exception:
                        pass


                if row in _initial_visible:
                    # Eager populate: this row is on the current page.
                    self._populate_single_row(row, segment)
                else:
                    # Cheap placeholder for off-page rows; pagination
                    # will lazy-populate full widgets on navigation.
                    self.table.removeCellWidget(row, 2)
                    self.table.removeCellWidget(row, 3)
                    self.table.removeCellWidget(row, 4)
                    self.table.removeCellWidget(row, 5)
                    _id_item = QTableWidgetItem(str(segment.id))
                    _id_item.setFlags(_id_item.flags() & ~Qt.ItemFlag.ItemIsEditable)
                    _id_item.setTextAlignment(Qt.AlignmentFlag.AlignCenter)
                    self.table.setItem(row, 0, _id_item)
                    _status_ph = QTableWidgetItem()
                    _status_ph.setFlags(Qt.ItemFlag.NoItemFlags)
                    _status_ph.setBackground(QColor(get_status(segment.status).color))
                    self.table.setItem(row, 4, _status_ph)


            # v1.10.148: per-row fonts are already set by _populate_single_row
            # at construction time, so the per-row pass of apply_font_to_grid
            # is pure duplicated work here (~9 s on a 479-segment SDLXLIFF).
            # Pass skip_per_row=True to do only the table-wide font/header/
            # column-width tweaks. The full pass still runs when the user
            # changes the font from the menu.
            self.apply_font_to_grid(skip_per_row=True)

            # Auto-resize rows
            self.auto_resize_rows()
            self._enforce_status_row_heights()

            self.log(f"✓ Loaded {len(self.current_project.segments)} segments to grid")

            # Apply pagination - show only segments for current page
            self._apply_pagination_to_grid()

            # Reposition file boundary banners (pagination may have changed row visibility)
            self._update_file_boundary_labels()

            # Apply current tag view mode (WYSIWYG or Tags)
            if hasattr(self, 'show_tags') and self.show_tags:
                # If tags mode is enabled, refresh to show raw tags
                self._refresh_grid_display_mode()

            # Also refresh List view if it exists
            if hasattr(self, 'list_tree'):
                self.refresh_list_view()
        finally:
            self._suppress_target_change_handlers = previous_suppression
            
            # NOW unblock all target editor signals - grid loading is complete
            # This MUST happen after suppression flag is restored to avoid race conditions
            for row in range(self.table.rowCount()):
                target_widget = self.table.cellWidget(row, 3)
                if target_widget:
                    target_widget.blockSignals(False)

            # v1.10.57 Phase C: paint background highlight on any
            # anchored comment ranges. Done after all cells are
            # populated and signals are unblocked, so the highlight
            # applies to the final character formatting layer.
            try:
                self._apply_comment_anchors_to_all_cells()
            except Exception as e:
                self.log(f"⚠ Anchor highlights skipped: {e}")

            # Update progress stats in status bar
            self.update_progress_stats()

            # Refresh document preview
            self.refresh_preview()

            # Deferred row resize: columns use Stretch mode, so their final widths
            # are only known after Qt processes the layout. Schedule a resize for
            # after all pending events are processed.
            QTimer.singleShot(0, self._resize_visible_rows)

    # =========================================================================
    # COMPARE PANEL TAB
    # =========================================================================

    def _create_compare_panel(self) -> QWidget:
        """Create the Compare Panel tab with 4 comparison boxes:
        Current Source, Machine Translation, TM Source, TM Target
        With navigation arrows for multiple matches.
        """
        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(8, 8, 8, 8)
        layout.setSpacing(4)
        
        # Get theme colors
        if hasattr(self, 'theme_manager') and self.theme_manager:
            theme = self.theme_manager.current_theme
            # Check if theme is dark by checking the theme name or a dark attribute
            is_dark = getattr(theme, 'is_dark', 'dark' in theme.name.lower())
            border_color = theme.border
            title_color = theme.text_disabled
            text_color = theme.text
            # Use theme-appropriate colors for boxes
            box1_bg = theme.panel_info if hasattr(theme, 'panel_info') else ("#2d3748" if is_dark else "#e3f2fd")
            box2_bg = theme.panel_warning if hasattr(theme, 'panel_warning') else ("#3d3520" if is_dark else "#fff3cd")
            box3_bg = theme.panel_success if hasattr(theme, 'panel_success') else ("#1e3a2f" if is_dark else "#d4edda")
            box4_bg = theme.panel_neutral if hasattr(theme, 'panel_neutral') else ("#2d2d3d" if is_dark else "#e8e8f0")
        else:
            is_dark = False
            border_color = "#ddd"
            title_color = "#666"
            text_color = "#333"
            box1_bg = "#e3f2fd"
            box2_bg = "#fff3cd"
            box3_bg = "#d4edda"
            box4_bg = "#e8e8f0"
        
        # Header with segment info
        header_layout = QHBoxLayout()
        self.compare_panel_segment_label = QLabel(self.tr("Segment: -"))
        self.compare_panel_segment_label.setStyleSheet(f"font-weight: bold; font-size: 11px; color: {title_color};")
        header_layout.addWidget(self.compare_panel_segment_label)
        header_layout.addStretch()
        layout.addLayout(header_layout)
        
        # Store text edits and navigation state for theme updates
        self.compare_panel_text_edits = []
        self.compare_panel_mt_matches = []  # List of MT matches
        self.compare_panel_tm_matches = []  # List of TM matches
        self.compare_panel_mt_index = 0     # Current MT match index
        self.compare_panel_tm_index = 0     # Current TM match index
        
        # Box 1: Current Source (blue-ish) - no navigation needed
        box1_container, self.compare_panel_current_source, _, _ = self._create_compare_panel_box(
            "📝 Current Source", box1_bg, text_color, border_color, has_navigation=False)
        layout.addWidget(box1_container, 1)
        
        # Box 2: Machine Translation (purple-ish) - with navigation
        box2_container, self.compare_panel_mt, self.compare_panel_mt_nav_label, mt_nav_btns = self._create_compare_panel_box(
            "🤖 MT", box4_bg, text_color, border_color, has_navigation=True, shortcut_badge_text="0", shortcut_badge_tooltip="Alt+0")
        if mt_nav_btns:
            mt_nav_btns[0].clicked.connect(lambda: self._compare_panel_nav_mt(-1))
            mt_nav_btns[1].clicked.connect(lambda: self._compare_panel_nav_mt(1))
        layout.addWidget(box2_container, 1)
        
        # Box 3: TM Source (yellow-ish) - with navigation
        box3_container, self.compare_panel_tm_source, self.compare_panel_tm_nav_label, tm_nav_btns = self._create_compare_panel_box(
            "📚 TM Source", box2_bg, text_color, border_color, has_navigation=True)
        if tm_nav_btns:
            tm_nav_btns[0].clicked.connect(lambda: self._compare_panel_nav_tm(-1))
            tm_nav_btns[1].clicked.connect(lambda: self._compare_panel_nav_tm(1))
        layout.addWidget(box3_container, 1)
        
        # Box 4: TM Target (green-ish) - syncs with TM Source navigation
        box4_container, self.compare_panel_tm_target, self.compare_panel_tm_target_label, _ = self._create_compare_panel_box(
            "✅ TM Target", box3_bg, text_color, border_color, has_navigation=False, show_metadata_label=True,
            shortcut_badge_text="00", shortcut_badge_tooltip="Alt+0,0")
        layout.addWidget(box4_container, 1)
        
        return widget
    
    def _create_match_panel(self) -> QWidget:
        """Create Match Panel with TermLens + TM Source/Target boxes."""
        widget = QWidget()
        main_layout = QVBoxLayout(widget)
        main_layout.setContentsMargins(0, 0, 0, 0)
        main_layout.setSpacing(0)
        
        # Initialize compare_panel_text_edits if not exists (needed for _create_compare_panel_box)
        if not hasattr(self, 'compare_panel_text_edits'):
            self.compare_panel_text_edits = []
        
        # Vertical splitter: TermLens (top) | TM boxes (bottom)
        splitter = QSplitter(Qt.Orientation.Vertical)
        
        # TOP: Container with header + TermLens
        termlens_container = QWidget()
        termlens_layout = QVBoxLayout(termlens_container)
        termlens_layout.setContentsMargins(4, 4, 4, 0)
        termlens_layout.setSpacing(2)
        
        # TermLens header row: label (left) + tip (right)
        if hasattr(self, 'theme_manager') and self.theme_manager:
            header_color = self.theme_manager.current_theme.text_disabled
        else:
            header_color = "#666"

        termlens_header_row = QHBoxLayout()
        termlens_header_row.setContentsMargins(0, 0, 0, 0)
        termlens_header_row.setSpacing(0)

        termlens_header = QLabel(self.tr("📖 TermLens"))
        termlens_header.setStyleSheet(f"font-weight: bold; font-size: 9pt; color: {header_color};")
        termlens_header_row.addWidget(termlens_header)

        termlens_header_row.addStretch()

        termlens_tip = QLabel(self.tr("💡 Tip: Press F5 to refresh if matches are missing"))
        termlens_tip.setStyleSheet(f"font-size: 9pt; color: {header_color}; font-style: italic;")
        termlens_header_row.addWidget(termlens_tip)

        termlens_layout.addLayout(termlens_header_row)
        
        # Third TermLens instance for Match Panel
        self.termlens_widget_match = TermLensWidget(self, db_manager=self.db_manager, log_callback=self.log, theme_manager=self.theme_manager)
        set_help_topic(self.termlens_widget_match, HelpTopics.GLOSSARY_TERMLENS)
        # Connect TermLens signals
        self.termlens_widget_match.term_insert_requested.connect(self.insert_termlens_text)
        self.termlens_widget_match.edit_entry_requested.connect(self._on_termlens_edit_entry)
        self.termlens_widget_match.delete_entry_requested.connect(self._on_termlens_delete_entry)
        # v1.10.68: refresh button on the Match-panel TermLens too —
        # both instances share the same backing index, so the handler
        # is the same.
        self.termlens_widget_match.refresh_requested.connect(self._on_termlens_refresh_requested)
        self.termlens_widget_match.font_size_changed.connect(self._on_termlens_font_size_changed)
        # Apply font settings
        font_settings = self.load_general_settings()
        termlens_family = font_settings.get('termlens_font_family', 'Segoe UI')
        termlens_size = font_settings.get('termlens_font_size', 10)
        termlens_bold = font_settings.get('termlens_font_bold', False)
        self.termlens_widget_match.set_font_settings(termlens_family, termlens_size, termlens_bold)
        termlens_layout.addWidget(self.termlens_widget_match)

        # Wrap the TermLens section + a QuickTrans panel in a tab pair, so the
        # user can have TermLens below the grid and QuickTrans here (or vice
        # versa). Mirrors the under-grid TermLens | QuickTrans dock.
        from PyQt6.QtWidgets import QTabWidget as _QTabWidget
        self.match_top_tabs = _QTabWidget()
        self.match_top_tabs.addTab(termlens_container, "📖 TermLens")
        try:
            from modules.quicktrans import QuickTransPanel
            self.quicktrans_panel_match = QuickTransPanel(self)
            self.quicktrans_panel_match.translation_selected.connect(self._insert_quicktrans_translation)
            self.match_top_tabs.addTab(self.quicktrans_panel_match, "⚡ QuickTrans")
            self.match_top_tabs.currentChanged.connect(self._on_match_top_tab_changed)
        except Exception as e:
            self.quicktrans_panel_match = None
            self.log(f"Could not create Match Panel QuickTrans panel: {e}")

        splitter.addWidget(self.match_top_tabs)
        
        # BOTTOM: Container for TM Source + TM Target boxes
        # v1.9.307: Store references for layout switching (horizontal ↔ vertical)
        # Default layout matches self.match_panel_tm_vertical (True = vertical)
        self._tm_container = QWidget()
        if getattr(self, 'match_panel_tm_vertical', True):
            self._tm_layout = QVBoxLayout(self._tm_container)
        else:
            self._tm_layout = QHBoxLayout(self._tm_container)
        self._tm_layout.setContentsMargins(0, 0, 0, 0)
        self._tm_layout.setSpacing(0)

        # Get theme-aware colors for TM boxes (same as Compare Panel)
        if hasattr(self, 'theme_manager') and self.theme_manager:
            theme = self.theme_manager.current_theme
            is_dark = getattr(theme, 'is_dark', 'dark' in theme.name.lower())
            border_color = theme.border
            text_color = theme.text
            # Green background - theme-appropriate shade
            tm_box_bg = theme.panel_success if hasattr(theme, 'panel_success') else ("#1e3a2f" if is_dark else "#d4edda")
        else:
            tm_box_bg = "#d4edda"    # Green (light mode)
            text_color = "#333"
            border_color = "#ddd"

        # TM Source box (GREEN, with navigation)
        self.match_panel_tm_matches = []  # Separate match list
        self.match_panel_tm_index = 0     # Separate navigation index

        self._tm_source_container, self.match_panel_tm_source, self.match_panel_tm_nav_label, tm_nav_btns = self._create_compare_panel_box(
            "📚 TM Source", tm_box_bg, text_color, border_color, has_navigation=True,
            add_fuzzy_fixer_button=True)
        if tm_nav_btns:
            tm_nav_btns[0].clicked.connect(lambda: self._match_panel_nav_tm(-1))
            tm_nav_btns[1].clicked.connect(lambda: self._match_panel_nav_tm(1))
        # Right-click context menu for TM Source
        self.match_panel_tm_source.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.match_panel_tm_source.customContextMenuRequested.connect(self._match_panel_tm_context_menu)
        self._tm_layout.addWidget(self._tm_source_container, 1)

        # TM Target box (GREEN, with metadata and shortcut badge)
        self._tm_target_container, self.match_panel_tm_target, self.match_panel_tm_target_label, _ = self._create_compare_panel_box(
            "✅ TM Target", tm_box_bg, text_color, border_color, has_navigation=False, show_metadata_label=True,
            shortcut_badge_text="0", shortcut_badge_tooltip="Alt+0")
        # Right-click context menu for TM Target
        self.match_panel_tm_target.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
        self.match_panel_tm_target.customContextMenuRequested.connect(self._match_panel_tm_context_menu)
        self._tm_layout.addWidget(self._tm_target_container, 1)

        # Force stylesheet on the tm_container itself (the parent widget holding both boxes)
        self._tm_container.setStyleSheet("background-color: transparent;")

        splitter.addWidget(self._tm_container)

        # Set initial splitter sizes (60% TermLens, 40% TM boxes)
        splitter.setSizes([600, 400])

        main_layout.addWidget(splitter)


        return widget

    def _toggle_match_panel_tm_layout(self, save=True):
        """Toggle TM Source / TM Target panes between horizontal (side-by-side)
        and vertical (stacked) layout in the Match Panel.

        v1.9.307: Accessible via right-click context menu and View > Match Panel menu.

        Args:
            save: If True, persist the preference to general_settings.json.
                  Set to False during startup restore to avoid redundant writes.
        """
        from PyQt6.QtWidgets import QHBoxLayout, QVBoxLayout

        if not hasattr(self, '_tm_container') or not hasattr(self, '_tm_source_container'):
            return

        # Remove widgets from current layout (keeps widget alive)
        self._tm_layout.removeWidget(self._tm_source_container)
        self._tm_layout.removeWidget(self._tm_target_container)

        # Delete the old layout by orphaning it onto a temporary widget
        QWidget().setLayout(self._tm_container.layout())

        # Flip the orientation
        self.match_panel_tm_vertical = not self.match_panel_tm_vertical

        # Create new layout with the desired orientation
        if self.match_panel_tm_vertical:
            self._tm_layout = QVBoxLayout(self._tm_container)
        else:
            self._tm_layout = QHBoxLayout(self._tm_container)
        self._tm_layout.setContentsMargins(0, 0, 0, 0)
        self._tm_layout.setSpacing(0)

        # Re-add widgets in the same order
        self._tm_layout.addWidget(self._tm_source_container, 1)
        self._tm_layout.addWidget(self._tm_target_container, 1)

        # Sync View menu checkbox
        if hasattr(self, 'match_panel_vertical_action'):
            self.match_panel_vertical_action.setChecked(self.match_panel_tm_vertical)

        # Persist preference
        if save:
            try:
                settings = self._load_general_settings_from_file()
                settings['match_panel_tm_vertical'] = self.match_panel_tm_vertical
                self.save_general_settings(settings)
            except Exception:
                pass

    def _match_panel_nav_tm(self, direction: int):
        """Navigate TM matches in Match Panel (-1 = prev, 1 = next)"""
        if not self.match_panel_tm_matches:
            return
        
        new_index = self.match_panel_tm_index + direction
        if 0 <= new_index < len(self.match_panel_tm_matches):
            self.match_panel_tm_index = new_index
            self._update_match_panel_tm_display()
    
    def _update_match_panel_tm_display(self):
        """Update Match Panel TM Source and TM Target display with current match"""
        if not self.match_panel_tm_matches:
            self.match_panel_tm_source.setPlainText("(No TM match)")
            self.match_panel_tm_target.setPlainText("(No TM match)")
            if hasattr(self, 'match_panel_tm_nav_label') and self.match_panel_tm_nav_label:
                self.match_panel_tm_nav_label.setText("(0/0)")
            if hasattr(self, 'match_panel_tm_target_label') and self.match_panel_tm_target_label:
                self.match_panel_tm_target_label.setText("")
            self._update_fuzzy_fixer_btn_state(None)
            return
        
        match = self.match_panel_tm_matches[self.match_panel_tm_index]
        total = len(self.match_panel_tm_matches)
        idx = self.match_panel_tm_index + 1

        # Support both dict and TranslationMatch objects
        if isinstance(match, dict):
            tm_source_text = match.get('source', '')
            target_text = match.get('target', '')
            tm_name = match.get('tm_name', 'Unknown TM')
            match_pct = match.get('match_pct', 0)
            reverse_match = match.get('reverse_match', False)
        else:
            tm_source_text = getattr(match, 'compare_source', '') or getattr(match, 'source', '')
            target_text = getattr(match, 'target', '')
            md = match.metadata if hasattr(match, 'metadata') and match.metadata else {}
            tm_name = md.get('tm_name', 'Unknown TM')
            match_pct = getattr(match, 'relevance', 0)
            reverse_match = bool(md.get('reverse_match', False))

        # Update navigation label
        if hasattr(self, 'match_panel_tm_nav_label') and self.match_panel_tm_nav_label:
            nav_html = f"(<span style='font-size:8px'>{idx}/{total}</span>)"
            self.match_panel_tm_nav_label.setText(nav_html)

        # Enable the FuzzyFixer button only when this match is in the configured range
        self._update_fuzzy_fixer_btn_state(match_pct)

        # Update TM Source text with diff highlighting
        # Strip any stale invisible markers from TM data before processing
        current_source = getattr(self, 'match_panel_current_source', '')
        clean_tm_source = tm_source_text
        if clean_tm_source and hasattr(self, 'reverse_invisible_replacements'):
            clean_tm_source = self.reverse_invisible_replacements(clean_tm_source)
        if clean_tm_source and current_source:
            self._set_compare_panel_text_with_diff(self.match_panel_tm_source, current_source, clean_tm_source)
        else:
            # Apply invisible replacements for display (e.g. ↵ for line breaks)
            tm_src_display = clean_tm_source or "(No TM match)"
            if clean_tm_source and hasattr(self, 'apply_invisible_replacements'):
                tm_src_display = self.apply_invisible_replacements(tm_src_display)
            self.match_panel_tm_source.setPlainText(tm_src_display)

        # A match that differs only in its inline codes gets the current
        # source's codes ({PK}{MN} → {PKMN}; issue #194)
        if target_text and current_source and tm_source_text:
            adapted = _inline_codes.adapt_codes(tm_source_text, target_text, current_source)
            if adapted is not None:
                target_text = adapted

        # Update TM Target text (no diff highlighting needed for target)
        # Strip any stale invisible markers first (in case TM data was saved with markers),
        # then re-apply current invisible display settings for clean rendering
        target_display = target_text if target_text else ""
        if target_display and hasattr(self, 'reverse_invisible_replacements'):
            target_display = self.reverse_invisible_replacements(target_display)
        if target_display and hasattr(self, 'apply_invisible_replacements'):
            target_display = self.apply_invisible_replacements(target_display)
        self.match_panel_tm_target.setPlainText(target_display)

        # Update metadata label (TM name, percentage, optional reverse-match chip)
        if hasattr(self, 'match_panel_tm_target_label') and self.match_panel_tm_target_label:
            # v1.10.50: append a small "⇄ reversed" chip when the match came
            # from a TM whose source/target languages are the inverse of this
            # project's. The chip uses a muted amber colour so it reads as
            # "informational, not alarming." Tooltip on the label spells it
            # out for users who don't recognise the symbol.
            reverse_chip = ""
            if reverse_match:
                reverse_chip = (
                    " <span style='font-size:8px; color:#b45309; "
                    "background-color:rgba(245,158,11,0.18); "
                    "padding:1px 5px; border-radius:6px;'>⇄ reversed</span>"
                )
                # v1.10.52: wrap tooltip text in HTML with explicit colours
                # so it survives Windows-11 OS-level tooltip rendering, which
                # in dark mode ignores both the per-widget QToolTip stylesheet
                # and the QPalette ToolTipBase/Text roles. Inline HTML in the
                # tooltip text itself is always honoured.
                self.match_panel_tm_target_label.setToolTip(
                    "<div style='background-color:#1f2937; color:#f9fafb; "
                    "padding:6px 8px; max-width:360px;'>"
                    "This match comes from a TM whose source/target languages "
                    "are the inverse of this project. The match is from the "
                    "TM's target column; Workbench has swapped fields so it "
                    "displays normally."
                    "</div>"
                )
            else:
                self.match_panel_tm_target_label.setToolTip("")
            metadata_html = (
                f"<span style='font-size:10px'>{tm_name}</span> "
                f"(<span style='font-size:8px'>{match_pct}%</span>)"
                f"{reverse_chip}"
            )
            self.match_panel_tm_target_label.setText(metadata_html)
    
    def _match_panel_tm_context_menu(self, pos):
        """Right-click context menu for the TM Source / TM Target boxes in the Match Panel."""
        from PyQt6.QtWidgets import QMenu
        from PyQt6.QtGui import QAction

        sender = self.sender()
        menu = sender.createStandardContextMenu()

        # Fix blurry context menu rendering (high-DPI / transparent background inheritance)
        menu.setStyleSheet("""
            QMenu {
                background-color: palette(window);
                border: 1px solid palette(mid);
            }
            QMenu::item {
                padding: 4px 20px;
            }
            QMenu::item:selected {
                background-color: palette(highlight);
                color: palette(highlighted-text);
            }
            QMenu::separator {
                height: 1px;
                background: palette(mid);
                margin: 4px 8px;
            }
        """)

        # v1.9.307: Layout toggle – always available (even with no TM matches)
        menu.addSeparator()
        is_vertical = getattr(self, 'match_panel_tm_vertical', True)
        layout_action = QAction("↕ Stack TM Source / Target Vertically", menu)
        layout_action.setCheckable(True)
        layout_action.setChecked(is_vertical)
        layout_action.triggered.connect(lambda _checked: self._toggle_match_panel_tm_layout())
        menu.addAction(layout_action)

        if not self.match_panel_tm_matches:
            menu.exec(sender.mapToGlobal(pos))
            return

        match = self.match_panel_tm_matches[self.match_panel_tm_index]

        # Support both dict and TranslationMatch objects
        if isinstance(match, dict):
            tm_id = match.get('tm_id', '')
            tm_name = match.get('tm_name', '') or tm_id or 'TM'
        else:
            # TranslationMatch object
            tm_id = match.metadata.get('tm_id', '') if hasattr(match, 'metadata') and match.metadata else ''
            tm_name = match.metadata.get('tm_name', '') if hasattr(match, 'metadata') and match.metadata else ''
            tm_name = tm_name or tm_id or 'TM'

        menu.addSeparator()
        edit_action = QAction(f"✏️ Edit TM Entry ({tm_name})", menu)
        edit_action.triggered.connect(self._match_panel_edit_tm_entry)
        if not tm_id:
            edit_action.setEnabled(False)
            edit_action.setText(self.tr("✏️ Edit TM Entry (no TM ID available)"))
        menu.addAction(edit_action)

        delete_action = QAction(f"🗑️ Delete TM Entry ({tm_name})", menu)
        delete_action.triggered.connect(self._match_panel_delete_tm_entry)
        if not tm_id:
            delete_action.setEnabled(False)
            delete_action.setText(self.tr("🗑️ Delete TM Entry (no TM ID available)"))
        menu.addAction(delete_action)

        menu.exec(sender.mapToGlobal(pos))

    def _get_match_panel_tm_fields(self, match):
        """Extract tm_id, tm_name, source, target from a Match Panel match (dict or TranslationMatch)."""
        if isinstance(match, dict):
            return (match.get('tm_id', ''),
                    match.get('tm_name', '') or match.get('tm_id', '') or 'TM',
                    match.get('source', ''),
                    match.get('target', ''))
        else:
            md = match.metadata if hasattr(match, 'metadata') and match.metadata else {}
            return (md.get('tm_id', ''),
                    md.get('tm_name', '') or md.get('tm_id', '') or 'TM',
                    getattr(match, 'source', ''),
                    getattr(match, 'target', ''))

    def _match_panel_edit_tm_entry(self):
        """Edit the TM entry currently displayed in the Match Panel."""
        if not self.match_panel_tm_matches:
            return

        from PyQt6.QtWidgets import (QDialog, QVBoxLayout, QLabel,
                                     QTextEdit, QDialogButtonBox, QMessageBox)

        match = self.match_panel_tm_matches[self.match_panel_tm_index]
        tm_id, tm_name, old_source, old_target = self._get_match_panel_tm_fields(match)

        if not tm_id:
            QMessageBox.warning(self, "Cannot Edit",
                                "TM identifier is not available for this entry.")
            return

        dialog = QDialog(self)
        dialog.setWindowTitle(f"Edit TM Entry – {tm_name}")
        dialog.setMinimumWidth(520)
        layout = QVBoxLayout(dialog)
        layout.setSpacing(8)

        layout.addWidget(QLabel(self.tr("Source (read-only):")))
        source_edit = QTextEdit()
        source_edit.setPlainText(old_source)
        source_edit.setReadOnly(True)
        source_edit.setMaximumHeight(90)
        layout.addWidget(source_edit)

        layout.addWidget(QLabel(self.tr("Target:")))
        target_edit = QTextEdit()
        target_edit.setPlainText(old_target)
        target_edit.setMaximumHeight(120)
        layout.addWidget(target_edit)

        buttons = QDialogButtonBox(
            QDialogButtonBox.StandardButton.Ok | QDialogButtonBox.StandardButton.Cancel
        )
        buttons.accepted.connect(dialog.accept)
        buttons.rejected.connect(dialog.reject)
        layout.addWidget(buttons)

        if dialog.exec() != QDialog.DialogCode.Accepted:
            return

        new_target = target_edit.toPlainText()
        if new_target == old_target:
            return  # Nothing changed

        updated = False
        try:
            if hasattr(self, 'tm_manager') and self.tm_manager and hasattr(self.tm_manager, 'update_entry'):
                updated = self.tm_manager.update_entry(tm_id, old_source, old_target,
                                                       old_source, new_target)
            elif hasattr(self, 'db_manager') and self.db_manager and hasattr(self.db_manager, 'update_entry'):
                updated = self.db_manager.update_entry(tm_id, old_source, old_target,
                                                       old_source, new_target)
        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to update TM entry:\n{e}")
            return

        if updated:
            self.log(f"✏️ Updated TM entry in '{tm_name}'")
            # Patch the in-memory match so the display reflects the change immediately
            if isinstance(match, dict):
                match['target'] = new_target
            else:
                match.target = new_target
            self._update_match_panel_tm_display()
            # Force re-lookup next time this segment is navigated to
            if hasattr(self, '_last_selected_row'):
                self._last_selected_row = None
        else:
            QMessageBox.warning(self, "Not Found",
                                "The entry could not be found in the database.\n"
                                "It may have already been changed or deleted.")

    def _match_panel_delete_tm_entry(self):
        """Delete the TM entry currently displayed in the Match Panel."""
        if not self.match_panel_tm_matches:
            return

        from PyQt6.QtWidgets import QMessageBox

        match = self.match_panel_tm_matches[self.match_panel_tm_index]
        tm_id, tm_name, source_text, target_text = self._get_match_panel_tm_fields(match)

        if not tm_id:
            QMessageBox.warning(self, "Cannot Delete",
                                "TM identifier is not available for this entry.")
            return

        reply = QMessageBox.question(
            self,
            "Confirm Deletion",
            f"Delete TM entry from '{tm_name}'?\n\n"
            f"Source: {source_text[:120]}\n"
            f"Target: {target_text[:120]}\n\n"
            "This action cannot be undone.",
            QMessageBox.StandardButton.Yes | QMessageBox.StandardButton.No,
            QMessageBox.StandardButton.No
        )
        if reply != QMessageBox.StandardButton.Yes:
            return

        try:
            if hasattr(self, 'tm_manager') and self.tm_manager and hasattr(self.tm_manager, 'delete_entry'):
                self.tm_manager.delete_entry(tm_id, source_text, target_text)
            elif hasattr(self, 'db_manager') and self.db_manager and hasattr(self.db_manager, 'delete_entry'):
                self.db_manager.delete_entry(tm_id, source_text, target_text)
            else:
                QMessageBox.critical(self, "Error",
                                     "No TM manager available to perform deletion.")
                return
        except Exception as e:
            QMessageBox.critical(self, "Error", f"Failed to delete TM entry:\n{e}")
            return

        self.log(f"🗑️ Deleted TM entry from '{tm_name}'")

        # Remove from the in-memory list and update display
        self.match_panel_tm_matches.pop(self.match_panel_tm_index)
        # Clamp index in case we deleted the last item
        if self.match_panel_tm_index >= len(self.match_panel_tm_matches):
            self.match_panel_tm_index = max(0, len(self.match_panel_tm_matches) - 1)
        self._update_match_panel_tm_display()

        # Force re-lookup next time this segment is navigated to
        if hasattr(self, '_last_selected_row'):
            self._last_selected_row = None

    def _create_compare_panel_box(self, label: str, bg_color: str, text_color: str, border_color: str,
                                   has_navigation: bool = False, show_metadata_label: bool = False,
                                   shortcut_badge_text: str = None, shortcut_badge_tooltip: str = None,
                                   add_fuzzy_fixer_button: bool = False) -> tuple:
        """Create a single comparison box for the Compare Panel
        
        Returns: (container, text_edit, nav_label, nav_buttons) where nav_buttons is [prev_btn, next_btn] or None
        """
        container = QFrame()
        container.setStyleSheet(f"""
            QFrame {{
                background-color: {bg_color};
                border: 1px solid {border_color};
                border-radius: 4px;
            }}
        """)
        
        main_layout = QVBoxLayout(container)
        main_layout.setContentsMargins(6, 4, 6, 6)
        main_layout.setSpacing(2)
        
        # Header row with label, navigation, and metadata
        header_layout = QHBoxLayout()
        header_layout.setSpacing(4)
        
        # Title label
        title_label = QLabel(label)
        title_label.setStyleSheet(f"font-weight: bold; font-size: 9pt; color: {text_color}; background: transparent; border: none;")
        header_layout.addWidget(title_label)

        # Optional shortcut badge (TermLens-style blue bubble)
        if shortcut_badge_text:
            badge_width = 14 if len(shortcut_badge_text) == 1 else 20
            badge_label = QLabel(shortcut_badge_text)
            badge_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            badge_label.setFixedSize(badge_width, 14)
            badge_label.setStyleSheet("""
                QLabel {
                    background-color: #1976D2;
                    color: white;
                    border-radius: 7px;
                    font-size: 9px;
                    font-weight: bold;
                    padding: 0px;
                }
            """)
            if shortcut_badge_tooltip:
                badge_label.setToolTip(
                    f"Press {format_shortcut_for_display(shortcut_badge_tooltip)} to insert"
                )
            header_layout.addWidget(badge_label)

        # Optional FuzzyFixer button (only the Match Panel TM Source box uses this)
        if add_fuzzy_fixer_button:
            from PyQt6.QtWidgets import QPushButton as _QPushButton
            ff_btn = _QPushButton("🔧 FuzzyFixer")
            ff_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            ff_btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            ff_btn.setToolTip(self.tr(
                "FuzzyFixer: ask the AI to adapt this fuzzy TM match to the "
                f"current source ({format_shortcut_for_display('Ctrl+Alt+F')})"))
            ff_btn.setStyleSheet("""
                QPushButton {
                    font-size: 8pt;
                    font-weight: bold;
                    padding: 1px 8px;
                    background-color: #FF7043;
                    color: white;
                    border: none;
                    border-radius: 3px;
                }
                QPushButton:hover { background-color: #F4511E; }
                QPushButton:disabled { background-color: #BDBDBD; color: #EEEEEE; }
                QPushButton:focus { outline: none; }
            """)
            ff_btn.clicked.connect(self.fuzzy_fix_current_segment)
            ff_btn.setEnabled(False)  # Enabled once an in-range match is shown
            self.match_panel_fuzzy_fixer_btn = ff_btn
            header_layout.addWidget(ff_btn)

        # Add stretch to push navigation controls to the right (aligned with scrollbar)
        header_layout.addStretch()

        nav_label = None
        nav_buttons = None

        if has_navigation or show_metadata_label:
            # Navigation: (1/3) ◄ ► provider_name • 95%
            nav_label = QLabel("(0/0)")
            nav_label.setStyleSheet(f"font-size: 9pt; color: {text_color}; background: transparent; border: none;")
            # Store color so later rich-text updates can preserve theme color
            nav_label._compare_text_color = text_color
            header_layout.addWidget(nav_label)

        if has_navigation:
            # Detect theme for arrow color
            is_dark_theme = hasattr(self, 'theme_manager') and self.theme_manager and 'dark' in self.theme_manager.current_theme.name.lower()
            arrow_color = "#FFFFFF" if is_dark_theme else "#333333"

            # Create clickable label class with theme update capability
            from PyQt6.QtCore import pyqtSignal

            class ClickableArrow(QLabel):
                clicked = pyqtSignal()

                def __init__(self, arrow_symbol, parent=None):
                    """arrow_symbol: '◀' or '▶'"""
                    self.arrow_symbol = arrow_symbol
                    super().__init__("", parent)
                    self.setCursor(Qt.CursorShape.PointingHandCursor)

                def set_color(self, color):
                    """Update arrow color for current theme"""
                    self.setStyleSheet(f"""
                        QLabel {{
                            color: {color};
                            background: transparent;
                            border: none;
                            font-size: 11px;
                            font-weight: bold;
                        }}
                    """)
                    self.setText(self.arrow_symbol)

                def mousePressEvent(self, event):
                    self.clicked.emit()
                    super().mousePressEvent(event)

            # Prev arrow - using ◀
            prev_btn = ClickableArrow("◀")
            prev_btn.set_color(arrow_color)
            prev_btn.setFixedSize(16, 16)
            prev_btn.setAlignment(Qt.AlignmentFlag.AlignCenter)
            header_layout.addWidget(prev_btn)

            # Next arrow - using ▶
            next_btn = ClickableArrow("▶")
            next_btn.set_color(arrow_color)
            next_btn.setFixedSize(16, 16)
            next_btn.setAlignment(Qt.AlignmentFlag.AlignCenter)
            header_layout.addWidget(next_btn)

            # Store reference for theme updates
            if not hasattr(self, 'theme_aware_arrows'):
                self.theme_aware_arrows = []
            self.theme_aware_arrows.extend([prev_btn, next_btn])

            nav_buttons = [prev_btn, next_btn]

        main_layout.addLayout(header_layout)
        
        # Text area
        text_edit = QTextEdit()
        text_edit.setReadOnly(True)
        _mp_font_size = SupervertalerQt.match_panel_font_size  # Use live value so saved zoom is respected
        text_edit.setStyleSheet(f"""
            QTextEdit {{
                background-color: transparent;
                border: none;
                font-size: {_mp_font_size}px;
                padding: 2px;
                color: {text_color};
            }}
        """)
        # Also set document default font so rich-text content (cursor-inserted diffs) respects size
        from PyQt6.QtGui import QFont as _QFont
        _doc_font = _QFont()
        if SupervertalerQt.match_panel_font_family:
            _doc_font.setFamily(SupervertalerQt.match_panel_font_family)
        _doc_font.setPointSize(_mp_font_size)
        _doc_font.setBold(SupervertalerQt.match_panel_font_bold)
        text_edit.document().setDefaultFont(_doc_font)
        text_edit.setMinimumHeight(50)
        main_layout.addWidget(text_edit, 1)
        
        # Track for font updates and theming
        self.compare_panel_text_edits.append((text_edit, title_label, container, bg_color))
        
        return container, text_edit, nav_label, nav_buttons
    
    def _compare_panel_nav_mt(self, direction: int):
        """Navigate MT matches in Compare Panel (-1 = prev, 1 = next)"""
        if not self.compare_panel_mt_matches:
            return
        
        new_index = self.compare_panel_mt_index + direction
        if 0 <= new_index < len(self.compare_panel_mt_matches):
            self.compare_panel_mt_index = new_index
            self._update_compare_panel_mt_display()
    
    def _compare_panel_nav_tm(self, direction: int):
        """Navigate TM matches in Compare Panel (-1 = prev, 1 = next)"""
        if not self.compare_panel_tm_matches:
            return
        
        new_index = self.compare_panel_tm_index + direction
        if 0 <= new_index < len(self.compare_panel_tm_matches):
            self.compare_panel_tm_index = new_index
            self._update_compare_panel_tm_display()
    
    def _update_compare_panel_mt_display(self):
        """Update MT section display with current match"""
        if not self.compare_panel_mt_matches:
            self.compare_panel_mt.setPlainText("(No MT available)")
            if hasattr(self, 'compare_panel_mt_nav_label') and self.compare_panel_mt_nav_label:
                self.compare_panel_mt_nav_label.setText("(0/0)")
            return
        
        match = self.compare_panel_mt_matches[self.compare_panel_mt_index]
        total = len(self.compare_panel_mt_matches)
        
        # Update navigation label with emphasis:
        # - Provider name: larger (readability)
        try:
            import html
            provider_escaped = html.escape(str(match.get('provider', 'MT')))
        except Exception:
            provider_escaped = str(match.get('provider', 'MT'))

        idx = self.compare_panel_mt_index + 1
        nav_html = (
            f"(<span style='font-size:8px'>{idx}/{total}</span>) "
            f"<span style='font-size:10px'>{provider_escaped}</span>"
        )

        if hasattr(self, 'compare_panel_mt_nav_label') and self.compare_panel_mt_nav_label:
            # Avoid a fixed font-size stylesheet overriding rich text emphasis, but keep theme color
            label_color = getattr(self.compare_panel_mt_nav_label, '_compare_text_color', None)
            if label_color:
                self.compare_panel_mt_nav_label.setStyleSheet(
                    f"color: {label_color}; background: transparent; border: none;"
                )
            else:
                self.compare_panel_mt_nav_label.setStyleSheet("background: transparent; border: none;")
            self.compare_panel_mt_nav_label.setText(nav_html)
        
        # Update text
        self.compare_panel_mt.setPlainText(match.get('translation', ''))
    
    def _update_compare_panel_tm_display(self):
        """Update TM Source and TM Target display with current match"""
        if not self.compare_panel_tm_matches:
            self.compare_panel_tm_source.setPlainText("(No TM match)")
            self.compare_panel_tm_target.setPlainText("(No TM match)")
            if hasattr(self, 'compare_panel_tm_nav_label') and self.compare_panel_tm_nav_label:
                self.compare_panel_tm_nav_label.setText("(0/0)")
            if hasattr(self, 'compare_panel_tm_target_label') and self.compare_panel_tm_target_label:
                self.compare_panel_tm_target_label.setText("(0/0)")
            return
        
        match = self.compare_panel_tm_matches[self.compare_panel_tm_index]
        total = len(self.compare_panel_tm_matches)

        # Get metadata
        tm_name = match.get('tm_name', 'TM')
        match_pct = match.get('match_pct', 0)
        reverse_match = bool(match.get('reverse_match', False))

        # Update metadata labels with emphasis:
        # - TM name: larger
        # - Match %: larger + bold
        try:
            import html
            tm_name_escaped = html.escape(str(tm_name))
        except Exception:
            tm_name_escaped = str(tm_name)

        idx = self.compare_panel_tm_index + 1
        try:
            match_pct_display = int(match_pct)
        except Exception:
            match_pct_display = match_pct

        # v1.10.50: optional "⇄ reversed" chip when the match came from a TM
        # whose source/target languages are the inverse of this project's.
        reverse_chip = ""
        if reverse_match:
            reverse_chip = (
                " <span style='font-size:8px; color:#b45309; "
                "background-color:rgba(245,158,11,0.18); "
                "padding:1px 5px; border-radius:6px;'>⇄ reversed</span>"
            )

        nav_html = (
            f"(<span style='font-size:8px'>{idx}/{total}</span>) "
            f"<span style='font-size:10px'>{tm_name_escaped}</span> "
            f"<span style='font-size:8px'>•</span> "
            f"<span style='font-size:10px; font-weight:700'>{match_pct_display}%</span>"
            f"{reverse_chip}"
        )

        # Tooltip on both labels (set whether or not chip is present so we
        # clear the tooltip when navigating away from a reversed match).
        # v1.10.52: wrap in HTML with explicit colours so the tooltip stays
        # readable under Windows-11 dark-mode tooltip rendering, which
        # ignores both QToolTip stylesheet and ToolTipBase/Text palette.
        reverse_tooltip = (
            "<div style='background-color:#1f2937; color:#f9fafb; "
            "padding:6px 8px; max-width:360px;'>"
            "This match comes from a TM whose source/target languages are "
            "the inverse of this project. The match is from the TM's "
            "target column; Workbench has swapped fields so it displays "
            "normally."
            "</div>"
        ) if reverse_match else ""

        if hasattr(self, 'compare_panel_tm_nav_label') and self.compare_panel_tm_nav_label:
            # Avoid a fixed font-size stylesheet overriding rich text emphasis, but keep theme color
            label_color = getattr(self.compare_panel_tm_nav_label, '_compare_text_color', None)
            if label_color:
                self.compare_panel_tm_nav_label.setStyleSheet(f"color: {label_color}; background: transparent; border: none;")
            else:
                self.compare_panel_tm_nav_label.setStyleSheet("background: transparent; border: none;")
            self.compare_panel_tm_nav_label.setText(nav_html)
            self.compare_panel_tm_nav_label.setToolTip(reverse_tooltip)

        if hasattr(self, 'compare_panel_tm_target_label') and self.compare_panel_tm_target_label:
            label_color = getattr(self.compare_panel_tm_target_label, '_compare_text_color', None)
            if label_color:
                self.compare_panel_tm_target_label.setStyleSheet(f"color: {label_color}; background: transparent; border: none;")
            else:
                self.compare_panel_tm_target_label.setStyleSheet("background: transparent; border: none;")
            self.compare_panel_tm_target_label.setText(nav_html)
            self.compare_panel_tm_target_label.setToolTip(reverse_tooltip)
        
        # Update TM Source with diff highlighting
        # Strip any stale invisible markers from TM data before processing
        current_source = self.compare_panel_current_source.toPlainText()
        tm_source = match.get('source', '')
        if tm_source and hasattr(self, 'reverse_invisible_replacements'):
            tm_source = self.reverse_invisible_replacements(tm_source)
        if tm_source and current_source:
            self._set_compare_panel_text_with_diff(self.compare_panel_tm_source, current_source, tm_source)
        else:
            # Apply invisible replacements for display (e.g. ↵ for line breaks)
            cp_src_display = tm_source or "(No TM match)"
            if tm_source and hasattr(self, 'apply_invisible_replacements'):
                cp_src_display = self.apply_invisible_replacements(cp_src_display)
            self.compare_panel_tm_source.setPlainText(cp_src_display)

        # Update TM Target – strip stale markers, then re-apply current settings
        tm_target_text = match.get('target', '')
        if tm_target_text and hasattr(self, 'reverse_invisible_replacements'):
            tm_target_text = self.reverse_invisible_replacements(tm_target_text)
        if tm_target_text and hasattr(self, 'apply_invisible_replacements'):
            tm_target_text = self.apply_invisible_replacements(tm_target_text)
        self.compare_panel_tm_target.setPlainText(tm_target_text)
    
    def set_compare_panel_matches(self, segment_id: int, current_source: str, 
                                   tm_matches: list = None, mt_matches: list = None):
        """Set all matches for Match Panel (and Compare Panel if it exists)
        
        Args:
            segment_id: Current segment ID
            current_source: The source text of the current segment
            tm_matches: List of dicts with keys: source, target, tm_name, match_pct
            mt_matches: List of dicts with keys: translation, provider
        """
        # Always update Match Panel with TM matches
        self.match_panel_tm_matches = tm_matches or []
        self.match_panel_tm_index = 0
        self.match_panel_current_source = current_source  # Store for diff highlighting
        self._update_match_panel_tm_display()
        
        # Update Compare Panel if it exists (legacy support)
        if hasattr(self, 'compare_panel_current_source') and self.compare_panel_current_source:
            # Update segment label
            if hasattr(self, 'compare_panel_segment_label'):
                self.compare_panel_segment_label.setText(f"Segment {segment_id + 1}")
            
            # Update Current Source
            self.compare_panel_current_source.setPlainText(current_source)
            
            # Store matches and reset indices
            self.compare_panel_tm_matches = tm_matches or []
            self.compare_panel_mt_matches = mt_matches or []
            self.compare_panel_tm_index = 0
            self.compare_panel_mt_index = 0
            
            # Update displays
            self._update_compare_panel_mt_display()
            self._update_compare_panel_tm_display()

    def update_compare_panel(self, segment_id: int, current_source: str, 
                              tm_source: str = "", tm_target: str = "", 
                              mt_translation: str = "", tm_match_percent: int = 0,
                              tm_name: str = "TM", mt_provider: str = "MT"):
        """Update the Match Panel with new data for the current segment (legacy single-match method)
        
        This is the legacy method that accepts single TM/MT matches. For multiple matches,
        use set_compare_panel_matches() instead.
        """
        # Convert to the new format and use set_compare_panel_matches
        tm_matches = []
        mt_matches = []
        
        if tm_source or tm_target:
            tm_matches = [{
                'source': tm_source,
                'target': tm_target,
                'tm_name': tm_name,
                'match_pct': tm_match_percent
            }]
        
        if mt_translation:
            mt_matches = [{
                'translation': mt_translation,
                'provider': mt_provider
            }]
        
        self.set_compare_panel_matches(segment_id, current_source, tm_matches, mt_matches)
    
    def _set_compare_panel_text_with_diff(self, text_edit: QTextEdit, current: str, tm_source: str):
        """
        Set text with diff highlighting using memoQ-style track changes view:
        - Normal text: identical to current
        - Red underline: text added in current (insertion)
        - Red strikethrough: text removed from TM (deletion)

        This displays the TM source annotated with tracked changes.
        Newline characters (\n) are preserved as actual line breaks in the display.
        """
        import difflib
        import re

        text_edit.clear()
        cursor = text_edit.textCursor()

        # Create formatters - memoQ track changes style
        normal_format = QTextCharFormat()

        # Red strikethrough for deletions (text in TM but not in current)
        delete_format = QTextCharFormat()
        delete_format.setForeground(QColor("#cc0000"))  # Red text
        delete_format.setFontStrikeOut(True)

        # Red underline for insertions (text in current but not in TM)
        add_format = QTextCharFormat()
        add_format.setForeground(QColor("#cc0000"))  # Red text
        add_format.setFontUnderline(True)

        # Word-level diff in which inline tags are tokens of their own and the
        # original spacing is kept (modules/tm_diff.py, issue #117). Before,
        # "<b>tap</b>" → "<b>valve</b>" marked the tags as changed too.
        from modules.tm_diff import word_diff
        show_linebreaks = (hasattr(self, 'invisible_display_settings')
                           and self.invisible_display_settings.get('linebreaks', False))
        formats = {'normal': normal_format, 'delete': delete_format, 'add': add_format}
        previous = None
        for kind, text in word_diff(current, tm_source):
            fmt = formats[kind]
            # Keep a struck-through word and its replacement apart
            if (previous is not None and previous[0] == 'delete' and kind == 'add'
                    and not previous[1][-1:].isspace() and not text[:1].isspace()):
                cursor.insertText(' ', normal_format)
            for n, line in enumerate(text.split('\n')):
                if n:
                    # Show ↵ marker if linebreaks invisibles are enabled
                    if show_linebreaks:
                        cursor.insertText('↵', fmt)
                    cursor.insertBlock()
                if line:
                    cursor.insertText(line, fmt)
            previous = (kind, text)

        text_edit.setTextCursor(cursor)
    
    def _refresh_compare_panel_theme(self):
        """Refresh Match Panel TM box colors based on current theme"""
        if not hasattr(self, 'compare_panel_text_edits'):
            return
        
        # Get theme colors
        if hasattr(self, 'theme_manager') and self.theme_manager:
            theme = self.theme_manager.current_theme
            # Check if theme is dark by checking the theme name or a dark attribute
            is_dark = getattr(theme, 'is_dark', 'dark' in theme.name.lower())
            border_color = theme.border
            text_color = theme.text
            # Use theme-appropriate colors for Match Panel boxes (both green)
            panel_success = theme.panel_success if hasattr(theme, 'panel_success') else ("#1e3a2f" if is_dark else "#d4edda")
            box_colors = [
                panel_success,  # 0: Match Panel - TM Source (green)
                panel_success,  # 1: Match Panel - TM Target (green)
            ]
        else:
            return
        
        # Update each box
        for i, (text_edit, label_widget, container, _) in enumerate(self.compare_panel_text_edits):
            bg_color = box_colors[i] if i < len(box_colors) else box_colors[-1]
            
            container.setStyleSheet(f"""
                QFrame {{
                    background-color: {bg_color};
                    border: 1px solid {border_color};
                    border-radius: 4px;
                }}
            """)
            
            label_widget.setStyleSheet(f"font-weight: bold; font-size: 9px; color: {text_color}; background: transparent; border: none;")
            
            text_edit.setStyleSheet(f"""
                QTextEdit {{
                    background-color: transparent;
                    border: none;
                    font-size: 10px;
                    padding: 2px;
                    color: {text_color};
                }}
            """)

    # =========================================================================
    # DOCUMENT PREVIEW TAB
    # =========================================================================

    def _create_preview_tab(self, with_popout_button: bool = True) -> QWidget:
        """Create the Preview widget with live document preview and click-to-navigate.

        Used for both the in-panel Preview tab and (with_popout_button=False) the
        detached pop-out window. Both register in self.preview_widgets, so they
        stay in sync via refresh_preview / _scroll_preview_to_segment."""
        from PyQt6.QtWidgets import QScrollArea, QHBoxLayout, QPushButton

        widget = QWidget()
        layout = QVBoxLayout(widget)
        layout.setContentsMargins(0, 0, 0, 0)
        layout.setSpacing(0)

        # Small top bar: text size (issue #70) and, in the docked tab, "Pop out".
        bar = QHBoxLayout()
        bar.setContentsMargins(6, 4, 6, 2)
        zoom_out_btn = QPushButton("A−")
        zoom_out_btn.setToolTip(self.tr("Smaller text (Ctrl+mouse wheel also zooms)"))
        zoom_label = QPushButton(f"{round(self._get_preview_zoom() * 100)}%")
        zoom_label.setFlat(True)
        zoom_label.setToolTip(self.tr("Text size – click to reset to 100%"))
        zoom_in_btn = QPushButton("A+")
        zoom_in_btn.setToolTip(self.tr("Larger text (Ctrl+mouse wheel also zooms)"))
        for btn, step in ((zoom_out_btn, -1), (zoom_label, 0), (zoom_in_btn, 1)):
            btn.setCursor(Qt.CursorShape.PointingHandCursor)
            btn.setFocusPolicy(Qt.FocusPolicy.NoFocus)
            btn.setMinimumWidth(34)
            btn.clicked.connect(lambda _checked=False, st=step: self._step_preview_zoom(st))
            bar.addWidget(btn)
        widget.preview_zoom_label = zoom_label
        bar.addStretch(1)
        if with_popout_button:
            popout_btn = QPushButton(self.tr("⧉ Pop out"))
            popout_btn.setToolTip(self.tr("Open the preview in a separate, resizable window"))
            popout_btn.setCursor(Qt.CursorShape.PointingHandCursor)
            popout_btn.clicked.connect(self._open_preview_window)
            bar.addWidget(popout_btn)
        layout.addLayout(bar)

        # Create scroll area for the preview
        scroll_area = QScrollArea()
        scroll_area.setWidgetResizable(True)
        scroll_area.setStyleSheet("border: none;")

        # Create the preview text widget. A tiny QTextEdit subclass draws a thin
        # outline box around the current segment (memoQ-style) directly in the
        # viewport — Qt char formats can't render a per-run border, so we paint it
        # ourselves. Position is shown as a frame, never a fill, so it never
        # competes with the status tint.
        main_window = self

        class _PreviewTextEdit(QTextEdit):
            current_box_range = None  # (start_pos, end_pos) of the current segment

            def wheelEvent(self, event):
                # Ctrl+wheel zooms the preview text (issue #70)
                if event.modifiers() & Qt.KeyboardModifier.ControlModifier:
                    delta = event.angleDelta().y()
                    if delta:
                        main_window._step_preview_zoom(1 if delta > 0 else -1)
                    event.accept()
                    return
                super().wheelEvent(event)

            def paintEvent(self, event):
                super().paintEvent(event)
                rng = self.current_box_range
                if not rng:
                    return
                try:
                    from PyQt6.QtGui import QPainter, QPen
                    start, end = rng
                    c = self.textCursor()
                    c.setPosition(max(0, start))
                    r1 = self.cursorRect(c)
                    c.setPosition(min(end, self.document().characterCount() - 1))
                    r2 = self.cursorRect(c)
                    top = min(r1.top(), r2.top()) - 3
                    bottom = max(r1.bottom(), r2.bottom()) + 3
                    vp = self.viewport().rect()
                    left = vp.left() + 3
                    right = vp.right() - 3
                    painter = QPainter(self.viewport())
                    painter.setRenderHint(QPainter.RenderHint.Antialiasing, True)
                    pen = QPen(QColor('#2563eb'))  # blue = "you are here" (position, not status)
                    pen.setWidth(1)
                    painter.setPen(pen)
                    painter.drawRoundedRect(left, top, right - left, bottom - top, 4, 4)
                    painter.end()
                except Exception:
                    pass

        preview_text = _PreviewTextEdit()
        preview_text.setReadOnly(True)
        preview_text.setStyleSheet("""
            QTextEdit {
                background-color: white;
                border: none;
                padding: 20px 30px;
                font-family: Georgia, 'Times New Roman', serif;
                font-size: 11pt;
                line-height: 1.5;
            }
        """)

        # Enable click handling for navigation
        preview_text.mousePressEvent = lambda event: self._on_preview_click(event, preview_text)
        preview_text.setCursor(Qt.CursorShape.PointingHandCursor)

        scroll_area.setWidget(preview_text)
        layout.addWidget(scroll_area)

        # Store reference for updates
        widget.preview_text = preview_text
        widget.scroll_area = scroll_area

        # Track segment positions for click navigation
        widget.segment_positions = {}  # {(start_pos, end_pos): segment_id}

        # Track current highlighted segment
        widget.current_highlighted_segment_id = None

        # Hidden previews are not re-rendered on every change (issue #185), so
        # catch up when this one is shown – tab switch, pop-out window, or the
        # main window appearing with a project already loaded.
        widget.preview_sig = None

        def _showEvent(event, _w=widget, _base=widget.showEvent):
            _base(event)
            if getattr(_w, 'preview_sig', None) is None:
                from PyQt6.QtCore import QTimer
                QTimer.singleShot(0, self._refresh_preview_on_show)
        widget.showEvent = _showEvent

        # Store reference in instance for easy access
        if not hasattr(self, 'preview_widgets'):
            self.preview_widgets = []
        self.preview_widgets.append(widget)

        return widget

    def _open_preview_window(self):
        """Open the Document Preview in its own resizable top-level window.

        The window hosts a second preview widget registered in
        self.preview_widgets, so it tracks edits live (refresh_preview) and
        follows the current segment (_scroll_preview_to_segment) just like the
        docked tab — and clicking a sentence in it still jumps the grid there.
        Closing the window unregisters its widget."""
        from PyQt6.QtWidgets import QMainWindow

        existing = getattr(self, '_preview_window', None)
        if existing is not None:
            try:
                existing.raise_()
                existing.activateWindow()
                return
            except RuntimeError:
                self._preview_window = None  # previous window was destroyed

        win = QMainWindow(self)
        win.setWindowTitle(self.tr("Supervertaler — Document Preview"))
        win.setWindowFlag(Qt.WindowType.Window, True)
        pv = self._create_preview_tab(with_popout_button=False)
        win.setCentralWidget(pv)
        win.resize(720, 900)
        self._preview_window = win

        def _closeEvent(ev, _pv=pv):
            try:
                if hasattr(self, 'preview_widgets') and _pv in self.preview_widgets:
                    self.preview_widgets.remove(_pv)
            except Exception:
                pass
            self._preview_window = None
            ev.accept()
        win.closeEvent = _closeEvent

        try:
            self._render_preview(pv)
            pv.preview_sig = self._preview_content_signature()
        except Exception:
            pass
        win.show()
        win.raise_()
        win.activateWindow()

    def _toggle_preview_panel(self):
        """Toggle the right panel to the Document Preview tab and back (Ctrl+Alt+P).

        First press switches to Preview, remembering the tab you were on; pressing
        again returns to it (usually the Match Panel)."""
        if not getattr(self, 'right_tabs', None) or not hasattr(self, '_preview_tab_index'):
            return
        try:
            cur = self.right_tabs.currentIndex()
            if cur == self._preview_tab_index:
                prev = getattr(self, '_pre_preview_tab_index', 0)
                if prev is None or prev == self._preview_tab_index or prev >= self.right_tabs.count():
                    prev = 0  # Match Panel is the first right-panel tab
                self.right_tabs.setCurrentIndex(prev)
            else:
                self._pre_preview_tab_index = cur
                # Just switch — _on_right_tab_changed defers the refresh + highlight
                # to the next tick, so the tab itself appears instantly (and skips
                # re-rendering entirely when nothing has changed since last time).
                self.right_tabs.setCurrentIndex(self._preview_tab_index)
        except Exception:
            pass

    def _on_preview_click(self, event, preview_text: QTextEdit):
        """Handle click on preview text to navigate to corresponding segment"""
        from PyQt6.QtGui import QMouseEvent

        # Get cursor position from click
        cursor = preview_text.cursorForPosition(event.pos())
        click_pos = cursor.position()

        # Find which segment this position belongs to
        parent_widget = preview_text.parent()
        while parent_widget and not hasattr(parent_widget, 'segment_positions'):
            parent_widget = parent_widget.parent()

        if not parent_widget or not hasattr(parent_widget, 'segment_positions'):
            # Call parent's mousePressEvent for default behavior
            QTextEdit.mousePressEvent(preview_text, event)
            return

        segment_positions = parent_widget.segment_positions

        for (start_pos, end_pos), segment_id in segment_positions.items():
            if start_pos <= click_pos <= end_pos:
                # Navigate to this segment in the grid
                self._navigate_to_segment_in_grid(segment_id)
                break

        # Call parent's mousePressEvent for default behavior
        QTextEdit.mousePressEvent(preview_text, event)

    def _navigate_to_segment_in_grid(self, segment_id: int):
        """Navigate to a specific segment by ID in the grid"""
        if not self.current_project or not hasattr(self, 'table') or not self.table:
            return

        # Find the row for this segment ID
        for row in range(self.table.rowCount()):
            id_item = self.table.item(row, 0)
            if id_item:
                try:
                    row_segment_id = int(id_item.text())
                    if row_segment_id == segment_id:
                        # Switch to Grid tab first
                        if hasattr(self, 'main_tabs'):
                            self.main_tabs.setCurrentIndex(0)  # Grid tab
                        
                        # Handle pagination - switch to correct page if needed
                        if hasattr(self, 'page_size_combo') and self.page_size_combo.currentText() != "All":
                            try:
                                page_size = int(self.page_size_combo.currentText())
                                target_page = (row // page_size) + 1
                                if hasattr(self, 'page_number_input'):
                                    self.page_number_input.setText(str(target_page))
                                    self.go_to_page()
                            except ValueError:
                                pass

                        # Select this row and focus the target cell
                        self.table.setCurrentCell(row, 3)  # Column 3 = Target
                        self.table.scrollToItem(self.table.item(row, 0), QTableWidget.ScrollHint.PositionAtCenter)
                        
                        target_widget = self.table.cellWidget(row, 3)
                        if target_widget:
                            target_widget.setFocus()
                            # Place cursor at end of text
                            if isinstance(target_widget, QTextEdit):
                                cursor = target_widget.textCursor()
                                cursor.movePosition(cursor.MoveOperation.End)
                                target_widget.setTextCursor(cursor)

                        self.log(f"📄 Preview: Navigated to segment {segment_id}")
                        return
                except (ValueError, AttributeError):
                    continue

    def _current_segment_source(self) -> Optional[str]:
        """Source text of the segment selected in the grid (used by the
        results panel to adapt inline codes in TM matches, issue #194)."""
        seg_id = self._get_current_segment_id()
        if seg_id is None:
            return None
        segments = self.current_project.segments
        row = self.table.currentRow()
        if 0 <= row < len(segments) and segments[row].id == seg_id:
            return segments[row].source
        for seg in segments:
            if seg.id == seg_id:
                return seg.source
        return None

    def _get_current_segment_id(self) -> Optional[int]:
        """Get the ID of the currently selected segment in the grid"""
        if not self.current_project or not hasattr(self, 'table') or not self.table:
            return None
        
        current_row = self.table.currentRow()
        if current_row < 0:
            return None
        
        id_item = self.table.item(current_row, 0)
        if id_item:
            try:
                return int(id_item.text())
            except (ValueError, AttributeError):
                pass
        
        return None

    def _is_preview_tab_active(self) -> bool:
        """Check if the Preview tab is currently selected in the right panel.
        
        Used to optimize performance by skipping heavy lookups when user is
        navigating in Preview mode (they're likely just reading, not translating).
        """
        if not hasattr(self, 'right_tabs') or not self.right_tabs:
            return False
        if not hasattr(self, '_preview_tab_index'):
            return False
        return self.right_tabs.currentIndex() == self._preview_tab_index

    def _scroll_preview_to_segment(self, segment_id: int):
        """Highlight + scroll to the current segment in every VISIBLE preview.

        Updates whichever previews are actually on screen — the docked Preview
        tab when it's the active tab AND/OR the popped-out window — and skips
        hidden ones, so grid navigation stays cheap. (Previously this was gated
        on the docked tab being active, so the pop-out window never followed the
        cursor once you switched the docked panel to another tab.)
        """
        if not hasattr(self, 'preview_widgets') or not self.preview_widgets:
            return
        if not self.current_project or not self.current_project.segments:
            return

        for widget in self.preview_widgets:
            if not hasattr(widget, 'segment_positions') or not hasattr(widget, 'preview_text'):
                continue
            # Only touch previews that are actually visible (docked tab current,
            # or pop-out window open). Hidden tab pages report isVisible() False.
            try:
                if not widget.isVisible():
                    continue
            except RuntimeError:
                continue

            preview_text = widget.preview_text

            # Reverse map: segment id → (start, end) for the current render.
            id2range = {sid: (s, e) for (s, e), sid in widget.segment_positions.items()}
            target = id2range.get(segment_id)
            if target is None:
                continue
            target_start, target_end = target

            # O(1) highlight. _render_preview already paints every segment with its
            # status tint, so we only repaint TWO segments here: restore the
            # previously-highlighted one to its status tint, then tint the new
            # current one light-blue. (Re-painting all ~500 segments cost ~2s on a
            # large file — on every toggle AND every arrow-key move with the
            # preview open. This brings it down to a couple of cursor operations.)
            def _status_bg(_sid):
                _seg = next((x for x in self.current_project.segments if x.id == _sid), None)
                if _seg and _seg.status in ('confirmed', 'approved', 'proofread'):
                    return QColor('white')
                return QColor('#fff5e0')

            def _paint(_s, _e, _color):
                _c = preview_text.textCursor()
                _c.setPosition(_s)
                _c.setPosition(_e, QTextCursor.MoveMode.KeepAnchor)
                _f = _c.charFormat()
                _f.setBackground(_color)
                _c.mergeCharFormat(_f)

            prev_id = getattr(widget, 'current_highlighted_segment_id', None)
            if prev_id is not None and prev_id != segment_id and prev_id in id2range:
                _ps, _pe = id2range[prev_id]
                _paint(_ps, _pe, _status_bg(prev_id))

            _paint(target_start, target_end, QColor('#cfe3ff'))  # current segment (precise)
            widget.current_highlighted_segment_id = segment_id

            # Disable the old full-width outline box — the precise fill above is
            # now the current-segment indicator.
            if hasattr(preview_text, 'current_box_range'):
                preview_text.current_box_range = None
                preview_text.viewport().update()

            # Now scroll to the target segment, centered in viewport
            scroll_cursor = preview_text.textCursor()
            scroll_cursor.setPosition(target_start)
            preview_text.setTextCursor(scroll_cursor)
            self._center_cursor_in_preview(preview_text)

    def _center_cursor_in_preview(self, preview_text: QTextEdit):
        """Center the current cursor position in the preview viewport"""
        # Get the cursor rectangle (position in document coordinates)
        cursor_rect = preview_text.cursorRect()
        
        # Get viewport height
        viewport_height = preview_text.viewport().height()
        
        # Calculate scroll position to center the cursor
        # cursor_rect.top() is relative to the viewport, we need document position
        scrollbar = preview_text.verticalScrollBar()
        current_scroll = scrollbar.value()
        
        # The cursor rect top is relative to viewport, so add current scroll to get document position
        cursor_doc_y = current_scroll + cursor_rect.top()
        
        # Calculate target scroll to put cursor in center
        target_scroll = cursor_doc_y - (viewport_height // 2)
        
        # Clamp to valid scroll range
        target_scroll = max(0, min(target_scroll, scrollbar.maximum()))
        
        scrollbar.setValue(target_scroll)

    def _schedule_preview_refresh(self, delay_ms: int = 200):
        """Debounced live refresh of the Document Preview.

        Only re-renders while the Preview tab is actually visible — when it's
        hidden the refresh is skipped (it re-renders on show via
        _on_right_tab_changed), so editing stays cheap. Called on every target
        edit and on confirm so the preview tracks the document live: text flips
        from source to translation as you type, and the status background
        colours update as you confirm.
        """
        try:
            if not getattr(self, 'right_tabs', None) or not hasattr(self, '_preview_tab_index'):
                return
            if self.right_tabs.currentIndex() != self._preview_tab_index:
                return  # hidden — will refresh when its tab is next shown
            timer = getattr(self, '_preview_refresh_timer', None)
            if timer is None:
                from PyQt6.QtCore import QTimer
                timer = QTimer(self)
                timer.setSingleShot(True)
                timer.timeout.connect(self.refresh_preview)
                self._preview_refresh_timer = timer
            timer.start(delay_ms)
        except Exception:
            pass

    # ── Preview text size (issue #70) ────────────────────────────────
    PREVIEW_ZOOM_STEPS = (0.6, 0.7, 0.8, 0.9, 1.0, 1.1, 1.25, 1.4, 1.6, 1.8, 2.0, 2.5)

    def _get_preview_zoom(self) -> float:
        """Current preview zoom factor, loaded once from settings (1.0 = 100%)."""
        zoom = getattr(self, '_preview_zoom', None)
        if zoom is None:
            try:
                zoom = float(self.load_general_settings().get('preview_zoom', 1.0) or 1.0)
            except Exception:
                zoom = 1.0
            zoom = min(max(zoom, self.PREVIEW_ZOOM_STEPS[0]), self.PREVIEW_ZOOM_STEPS[-1])
            self._preview_zoom = zoom
        return zoom

    def _step_preview_zoom(self, direction: int):
        """Zoom the preview one step in (+1), out (-1), or back to 100% (0).
        Applies to every open preview (tab and pop-out) and is remembered."""
        current = self._get_preview_zoom()
        steps = self.PREVIEW_ZOOM_STEPS
        if direction == 0:
            zoom = 1.0
        elif direction > 0:
            zoom = next((z for z in steps if z > current + 1e-6), steps[-1])
        else:
            zoom = next((z for z in reversed(steps) if z < current - 1e-6), steps[0])
        if abs(zoom - current) < 1e-6:
            return
        self._preview_zoom = zoom
        try:
            settings = self.load_general_settings()
            settings['preview_zoom'] = zoom
            self.save_general_settings(settings)
        except Exception as e:
            self.log(f"⚠ Could not save preview zoom: {e}")
        for widget in getattr(self, 'preview_widgets', []) or []:
            label = getattr(widget, 'preview_zoom_label', None)
            if label is not None:
                label.setText(f"{round(zoom * 100)}%")
        self.refresh_preview(force=True)
        try:
            seg = self._get_current_segment_id()
            if seg is not None:
                self._scroll_preview_to_segment(seg)
        except Exception:
            pass

    def refresh_preview(self, force: bool = False):
        """Refresh all preview tabs with current document content.

        Skips the expensive full re-render when nothing affecting the preview has
        changed since the last render (compared via a cheap content signature) —
        so toggling the Preview on/off without editing is instant. Pass
        force=True to always re-render.
        """
        if not self.current_project or not self.current_project.segments:
            # Clear previews if no project
            if hasattr(self, 'preview_widgets'):
                for widget in self.preview_widgets:
                    if hasattr(widget, 'preview_text'):
                        widget.preview_text.clear()
                        widget.segment_positions = {}
                        widget.preview_sig = None
            return

        if not hasattr(self, 'preview_widgets') or not self.preview_widgets:
            return

        sig = self._preview_content_signature()
        for widget in [w for w in self.preview_widgets if hasattr(w, 'preview_text')]:
            try:
                visible = widget.isVisible()
            except RuntimeError:
                continue
            if not visible:
                # Issue #185: a hidden preview (the usual case – the Match Panel
                # is in front) is not rendered on every grid load; it renders
                # when it is shown (see showEvent in _create_preview_tab). On a
                # 17,000-segment import this render was most of the wait.
                widget.preview_sig = None
                continue
            if not force and widget.segment_positions and getattr(widget, 'preview_sig', None) == sig:
                continue  # already current – caller re-applies the current-segment highlight
            self._render_preview(widget)
            widget.preview_sig = sig

    def _preview_content_signature(self) -> str:
        """A cheap digest of everything the preview render depends on (segment
        text, status and structure). Lets refresh_preview skip redundant renders."""
        import hashlib
        h = hashlib.md5()
        for s in self.current_project.segments:
            h.update((
                f"{s.id}\x1f{s.source or ''}\x1f{s.target or ''}\x1f{s.status or ''}"
                f"\x1f{getattr(s, 'paragraph_id', '')}\x1f{getattr(s, 'type', '')}"
                f"\x1f{getattr(s, 'style', '')}\n"
            ).encode('utf-8', 'replace'))
        return h.hexdigest()

    def _refresh_preview_on_show(self):
        """Deferred preview refresh, run when the Preview tab becomes visible.

        Runs on the next event-loop tick so the tab switch paints first (the user
        is taken to the Preview immediately), then the content refreshes and the
        current segment is re-highlighted."""
        try:
            self.refresh_preview()
            seg = self._get_current_segment_id()
            if seg is not None:
                self._scroll_preview_to_segment(seg)
        except Exception as e:
            self.log(f"⚠ Preview refresh on show failed: {e}")

    def _render_preview(self, widget):
        """Render the document preview with realistic formatting"""
        if not hasattr(widget, 'preview_text'):
            return

        preview_text = widget.preview_text
        preview_text.clear()
        zoom = self._get_preview_zoom()  # issue #70: A-/A+ in the preview bar
        widget.segment_positions = {}
        # A fresh render repaints every segment with its status tint and clears the
        # highlight, so forget the previous current-segment (the O(1) highlight in
        # _scroll_preview_to_segment relies on this to avoid restoring a stale one).
        widget.current_highlighted_segment_id = None
        if hasattr(preview_text, 'current_box_range'):
            preview_text.current_box_range = None

        if not self.current_project or not self.current_project.segments:
            return

        cursor = preview_text.textCursor()
        cursor.movePosition(QTextCursor.MoveOperation.Start)
        # One edit block for the whole render: the document is laid out once at
        # the end instead of after every insert (issue #185).
        cursor.beginEditBlock()
        try:
            self._render_preview_segments(widget, preview_text, cursor, zoom)
        finally:
            cursor.endEditBlock()

        # Scroll to current segment if we have one
        if hasattr(widget, 'current_segment_start_pos') and widget.current_segment_start_pos is not None:
            # Create cursor at the current segment position
            scroll_cursor = preview_text.textCursor()
            scroll_cursor.setPosition(widget.current_segment_start_pos)
            preview_text.setTextCursor(scroll_cursor)
            # Center the segment in the viewport
            # Use QTimer to delay centering until after layout is complete
            from PyQt6.QtCore import QTimer
            QTimer.singleShot(0, lambda pt=preview_text: self._center_cursor_in_preview(pt))
        else:
            # Set cursor to beginning if no current segment
            cursor.movePosition(QTextCursor.MoveOperation.Start)
            preview_text.setTextCursor(cursor)

    def _render_preview_segments(self, widget, preview_text, cursor, zoom):
        """Insert every segment into the preview at ``cursor`` (see _render_preview)."""
        # Pre-calculate list numbers for numbered list items
        import re
        list_numbers = {}  # {segment_id: list_number}
        list_counter = 0
        prev_was_ordered_list = False

        for seg in self.current_project.segments:
            source_text = seg.source.strip() if seg.source else ""

            # Check for list tags (new <li-o>, <li-b> and legacy <li>)
            has_li_ordered = '<li-o>' in source_text or ('<li>' in source_text and '<li-b>' not in source_text)
            has_li_bullet = '<li-b>' in source_text

            if has_li_ordered:
                # Check for explicit number in text
                num_match = re.match(r'^<li(?:-o)?>\s*(\d+)[.)\s]', source_text)
                if num_match:
                    list_numbers[seg.id] = int(num_match.group(1))
                    list_counter = int(num_match.group(1))
                else:
                    # Reset counter if starting a new list (gap since last ordered item)
                    if not prev_was_ordered_list:
                        list_counter = 0
                    list_counter += 1
                    list_numbers[seg.id] = list_counter
                prev_was_ordered_list = True
            else:
                # Not an ordered list item - mark gap for potential new list
                prev_was_ordered_list = False

        # Render all segments
        current_segment_id = self._get_current_segment_id()
        segments = self.current_project.segments
        
        for idx, seg in enumerate(segments):
            style = getattr(seg, 'style', 'Normal') or 'Normal'
            paragraph_id = getattr(seg, 'paragraph_id', 0)
            seg_type = getattr(seg, 'type', 'para') or 'para'
            
            # Normalize type for comparison - grid shows symbols like "¶" for para, "Sub" for subtitle
            # Type field values: "para", "heading", "list_item", "table_cell", "Sub", "¶", etc.
            seg_type_lower = seg_type.lower() if seg_type else 'para'
            
            # Check if this is a list item (need source_text first)
            source_text = seg.source.strip() if seg.source else ""

            # Check if this is a heading/subtitle
            # Also detect bold-wrapped short text as section headings (e.g., <b>TECHNICAL FIELD</b>)
            is_heading = ('Heading' in style or 'Title' in style or 'Subtitle' in style
                          or seg_type_lower in ('heading', 'sub', 'subtitle', 'title'))

            # Detect bold section headings: <b>TEXT</b> where text is short and likely a heading
            if not is_heading and source_text.startswith('<b>') and source_text.endswith('</b>'):
                inner_text = source_text[3:-4].strip()  # Remove <b> and </b>
                # Short text (under 80 chars) that's bold is likely a section heading
                if len(inner_text) < 80 and '<' not in inner_text:
                    is_heading = True
            is_list_item = ('<li-o>' in source_text or '<li-b>' in source_text or 
                           '<li>' in source_text or seg_type_lower == 'list_item')
            
            # Check if this is a new paragraph (¶ symbol or "para" type)
            is_new_paragraph = seg_type == '¶' or seg_type_lower == 'para'
            
            # Determine spacing before this segment
            need_double_break = False  # Empty line (for paragraph separation)
            need_single_break = False  # Line break (for headings, list items)
            need_space = False         # Just a space (running text in same paragraph)
            
            if idx > 0:
                prev_seg = segments[idx - 1]
                prev_style = getattr(prev_seg, 'style', 'Normal') or 'Normal'
                prev_paragraph_id = getattr(prev_seg, 'paragraph_id', 0)
                prev_type = getattr(prev_seg, 'type', 'para') or 'para'
                prev_type_lower = prev_type.lower() if prev_type else 'para'
                
                prev_is_heading = ('Heading' in prev_style or 'Title' in prev_style or
                                   'Subtitle' in prev_style or
                                   prev_type_lower in ('heading', 'sub', 'subtitle', 'title'))
                # Also detect bold section headings in previous segment
                prev_source = prev_seg.source.strip() if prev_seg.source else ""
                if not prev_is_heading and prev_source.startswith('<b>') and prev_source.endswith('</b>'):
                    prev_inner = prev_source[3:-4].strip()
                    if len(prev_inner) < 80 and '<' not in prev_inner:
                        prev_is_heading = True
                prev_is_paragraph = prev_type == '¶' or prev_type_lower == 'para'
                prev_is_list = prev_type_lower == 'list_item' or '<li' in (prev_seg.source or '')
                
                # Rules for spacing:
                # 1. After a heading: double break (empty line)
                if prev_is_heading:
                    need_double_break = True
                # 2. Before a heading: double break
                elif is_heading:
                    need_double_break = True
                # 3. Paragraph flow. Sentences split from the SAME source paragraph
                #    share a paragraph_id, so they must join as running text — only a
                #    genuine paragraph_id change starts a new paragraph. (This mirrors
                #    how the export groups segments by paragraph_id.) When no
                #    paragraph_id is available (all-zero, e.g. some non-DOCX imports),
                #    fall back to treating each ¶ segment as its own paragraph.
                elif is_new_paragraph and prev_is_paragraph:
                    if paragraph_id == prev_paragraph_id and paragraph_id != 0:
                        # Same source paragraph → running text (this is what makes the
                        # preview follow the document's paragraph structure)
                        need_space = True
                    elif paragraph_id != prev_paragraph_id and (paragraph_id != 0 or prev_paragraph_id != 0):
                        # Genuinely different paragraphs
                        need_double_break = True
                    elif prev_type == '¶' and seg_type == '¶':
                        # No paragraph_id info → each ¶ is its own paragraph (fallback)
                        need_double_break = True
                    else:
                        # Same paragraph, running text
                        need_space = True
                # 4. List items: ordered list items (like claims) get paragraph spacing
                elif is_list_item or prev_is_list:
                    # Ordered list items (<li-o>) get double breaks for visual separation
                    is_ordered_list = '<li-o>' in source_text or ('<li>' in source_text and '<li-b>' not in source_text)
                    prev_is_ordered = '<li-o>' in (prev_seg.source or '') or ('<li>' in (prev_seg.source or '') and '<li-b>' not in (prev_seg.source or ''))
                    if is_ordered_list or prev_is_ordered:
                        need_double_break = True  # Paragraph-like spacing for numbered items
                    else:
                        need_single_break = True  # Bullet lists stay compact
                # 5. Default: space (running text)
                else:
                    need_space = True
            
            # Insert spacing/breaks
            if need_double_break:
                cursor.insertText("\n\n")  # Empty line between paragraphs
            elif need_single_break:
                cursor.insertText("\n")    # Line break
            elif need_space:
                cursor.insertText(" ")     # Space between sentences
            
            # Set formatting based on style
            char_format = QTextCharFormat()
            char_format.setFontFamily("Georgia")
            
            # Check type field for heading detection as well
            if is_heading and seg_type_lower in ('sub', 'subtitle'):
                # Subtitle style (like "TECHNISCH DOMEIN")
                char_format.setFontPointSize(13 * zoom)
                char_format.setFontWeight(QFont.Weight.Bold)
                char_format.setForeground(QColor('#1f4068'))
            elif 'Heading 1' in style or 'Heading1' in style or 'Title' in style or seg_type_lower == 'title':
                char_format.setFontPointSize(18 * zoom)
                char_format.setFontWeight(QFont.Weight.Bold)
                char_format.setForeground(QColor('#1a1a2e'))
            elif 'Heading 2' in style or 'Heading2' in style:
                char_format.setFontPointSize(15 * zoom)
                char_format.setFontWeight(QFont.Weight.Bold)
                char_format.setForeground(QColor('#16213e'))
            elif 'Heading 3' in style or 'Heading3' in style or seg_type_lower == 'heading':
                char_format.setFontPointSize(13 * zoom)
                char_format.setFontWeight(QFont.Weight.Bold)
                char_format.setForeground(QColor('#1f4068'))
            elif is_heading:
                # Bold section headings detected from <b>TEXT</b> pattern
                char_format.setFontPointSize(12 * zoom)
                char_format.setFontWeight(QFont.Weight.Bold)
                char_format.setForeground(QColor('#1a365d'))
            else:
                char_format.setFontPointSize(11 * zoom)
                char_format.setForeground(QColor('#2d2d2d'))

            # Determine what text to display
            if seg.target and seg.target.strip():
                display_text = seg.target
                is_translated = True
            else:
                display_text = seg.source if seg.source else ""
                is_translated = False

            # Status background (Option A — memoQ-minimal): a confirmed segment
            # reads as clean final text with no tint; anything unconfirmed gets a
            # single faint amber tint ("still to do"). The current segment is
            # marked by a thin blue outline box drawn in the viewport (see
            # _PreviewTextEdit.paintEvent), not a fill, so position never competes
            # with status.
            if seg.status in ('confirmed', 'approved', 'proofread'):
                char_format.setBackground(QColor('white'))  # done → blends with the page
            else:
                char_format.setBackground(QColor('#fff5e0'))  # unconfirmed → faint amber

            # Gray out untranslated text
            if not is_translated:
                char_format.setForeground(QColor('#888888'))
                char_format.setFontItalic(True)

            # Store position for click navigation
            start_pos = cursor.position()

            # Render text with list formatting
            self._render_formatted_text(cursor, display_text, char_format, 
                                        list_number=list_numbers.get(seg.id))

            end_pos = cursor.position()
            widget.segment_positions[(start_pos, end_pos)] = seg.id
            
            # Track position of current segment for scrolling + the outline box
            if seg.id == current_segment_id:
                widget.current_segment_start_pos = start_pos
                preview_text.current_box_range = (start_pos, end_pos)

            # Note: Line breaks are now handled at the START of each segment based on context
            # This ensures running text flows naturally while paragraphs are separated

        # Add final newline at end of document
        cursor.insertText("\n")

    def _render_formatted_text(self, cursor, text: str, base_format: QTextCharFormat,
                                list_number: Optional[int] = None):
        """Render text with list prefix and inline formatting tags preserved"""
        import re

        # Check for list tags
        has_li_bullet = '<li-b>' in text
        has_li_ordered = '<li-o>' in text or ('<li>' in text and '<li-b>' not in text)

        # Remove list tags from display  
        text = re.sub(r'</?li-b>', '', text)
        text = re.sub(r'</?li-o>', '', text)
        text = re.sub(r'</?li>', '', text)

        # Add list prefix if this is a list item
        if has_li_bullet or has_li_ordered:
            bullet_format = QTextCharFormat(base_format)
            bullet_format.setForeground(QColor('#ff6600'))  # Orange
            bullet_format.setFontWeight(QFont.Weight.Bold)
            bullet_format.setFontItalic(False)

            if has_li_ordered and list_number:
                cursor.insertText(f"{list_number}. ", bullet_format)
            elif has_li_ordered:
                cursor.insertText("• ", bullet_format)  # Fallback if no number
            else:
                cursor.insertText("• ", bullet_format)

        # Parse text for inline formatting tags
        tag_pattern = re.compile(r'(</?(?:b|i|u|bi|sub|sup)>)')
        parts = tag_pattern.split(text)

        is_bold = False
        is_italic = False
        is_underline = False
        is_subscript = False
        is_superscript = False

        for part in parts:
            if not part:
                continue

            if part == '<b>':
                is_bold = True
                continue
            elif part == '</b>':
                is_bold = False
                continue
            elif part == '<i>':
                is_italic = True
                continue
            elif part == '</i>':
                is_italic = False
                continue
            elif part == '<u>':
                is_underline = True
                continue
            elif part == '</u>':
                is_underline = False
                continue
            elif part == '<bi>':
                is_bold = True
                is_italic = True
                continue
            elif part == '</bi>':
                is_bold = False
                is_italic = False
                continue
            elif part == '<sub>':
                is_subscript = True
                continue
            elif part == '</sub>':
                is_subscript = False
                continue
            elif part == '<sup>':
                is_superscript = True
                continue
            elif part == '</sup>':
                is_superscript = False
                continue

            # Apply formatting to text
            text_format = QTextCharFormat(base_format)
            
            if is_bold:
                text_format.setFontWeight(QFont.Weight.Bold)
            if is_italic:
                text_format.setFontItalic(True)
            if is_underline:
                text_format.setUnderlineStyle(QTextCharFormat.UnderlineStyle.SingleUnderline)
            if is_subscript:
                text_format.setVerticalAlignment(QTextCharFormat.VerticalAlignment.AlignSubScript)
            if is_superscript:
                text_format.setVerticalAlignment(QTextCharFormat.VerticalAlignment.AlignSuperScript)

            cursor.insertText(part, text_format)

    def highlight_preview_segment(self, segment_id: Optional[int] = None):
        """Update the preview to highlight the specified segment (or current if None)"""
        if segment_id is None:
            segment_id = self._get_current_segment_id()
        
        if not segment_id:
            return
            
        # Store for later reference
        self._highlighted_segment_id = segment_id
        
        # Re-render preview to update highlighting
        # (In a full implementation, we'd just update the highlight without full re-render)

    # Comment-type colours shared by the Status-column indicator, the comment
    # panels and their legends (issue #234). SC = amber, PC = purple.
    COMMENT_SC_BG = "rgba(255, 152, 0, 0.35)"   # amber  – Segment Comments
    COMMENT_PC_BG = "rgba(156, 39, 176, 0.32)"  # purple – Proofreading Comments

    def _comment_indicator_bg(self, has_sc: bool, has_pc: bool):
        """Return a Qt-stylesheet ``background:`` value for the Status-column
        comment indicator, or None when the segment has no comments. Amber for
        Segment Comments, purple for Proofreading Comments, and a hard 50/50
        amber|purple split when a segment has both (issue #234 pt.1)."""
        if has_sc and has_pc:
            return (
                "qlineargradient(x1:0, y1:0, x2:1, y2:0, "
                f"stop:0 {self.COMMENT_SC_BG}, stop:0.499 {self.COMMENT_SC_BG}, "
                f"stop:0.5 {self.COMMENT_PC_BG}, stop:1 {self.COMMENT_PC_BG})"
            )
        if has_sc:
            return self.COMMENT_SC_BG
        if has_pc:
            return self.COMMENT_PC_BG
        return None

    def _create_status_cell_widget(self, segment: Segment) -> QWidget:
        widget = QWidget()
        layout = QHBoxLayout(widget)
        layout.setContentsMargins(2, 0, 2, 0)  # Zero vertical margins to prevent icon clipping on single-line rows
        layout.setSpacing(1)
        layout.setAlignment(Qt.AlignmentFlag.AlignVCenter)  # Center content vertically
        # Remove fixed minimum height - let it adapt to row height
        widget.setSizePolicy(QSizePolicy.Policy.Expanding, QSizePolicy.Policy.Expanding)
        # Note: Do NOT set WA_TransparentForMouseEvents - we want tooltips to work

        # Check if segment has notes or proofreading notes
        has_notes = bool(segment.notes and segment.notes.strip())
        has_proofreading = bool(getattr(segment, 'proofreading_notes', None))
        has_any_notes = has_notes or has_proofreading

        # Distinct Status-column backgrounds so Segment Comments (SC) and
        # Proofreading Comments (PC) are tellable apart at a glance (issue #234
        # pt.1): SC → amber, PC → purple, both → a hard amber|purple split.
        # `indicator_bg` is a Qt-stylesheet value usable with `background:`.
        indicator_bg = self._comment_indicator_bg(has_notes, has_proofreading)

        # Widget background always transparent
        widget.setStyleSheet("background: transparent;")
        if has_any_notes:
            tooltip_parts = []
            if has_notes:
                tooltip_parts.append(f"Segment comment: {segment.notes.strip()}")
            if has_proofreading:
                model_count = len(segment.proofreading_notes)
                tooltip_parts.append(f"Proofreading comment: {model_count} LLM result{'s' if model_count != 1 else ''}")
            widget.setToolTip("\n".join(tooltip_parts))

        # Comment access from the Status column (Trados-parity). Build a
        # tooltip from the segment's actual comments (anchored + segment-level)
        # and, when there are any, wire a right-click "Open comment(s)" menu so
        # segment-level comments — which have no highlighted range in the cells
        # — are reachable straight from the status indicator. The eventFilter
        # appends ``comment_tooltip`` to the hovered status glyph's tooltip.
        seg_comments = [c for c in (getattr(segment, 'comments', None) or [])
                        if c.text and c.text.strip()]
        if seg_comments:
            tip_lines = []
            for c in seg_comments[:4]:
                prefix = f"⚓{c.anchor_field} " if c.is_anchored else ""
                tip_lines.append(f"💬 {prefix}{c.text.strip()}")
            if len(seg_comments) > 4:
                tip_lines.append(f"…(+{len(seg_comments) - 4} more)")
            widget.setProperty("comment_tooltip", "\n".join(tip_lines))
            first_cid = seg_comments[0].id
            widget.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
            widget.customContextMenuRequested.connect(
                lambda pos, w=widget, cid=first_cid, n=len(seg_comments):
                    self._status_cell_comment_menu(w, pos, cid, n)
            )

        status_def = get_status(segment.status)

        # Status icons: ✔ (green text glyph) and ❌ (native emoji, ~16px on Windows)
        # Use CSS font-size for the checkmark to match the emoji size visually.
        # The ✔ is a text character so font-size controls it; emojis ignore font-size.
        # IMPORTANT: On single-line rows, vertical space is very tight (~20-24px).
        # The icon + container margins + QLabel internal padding must fit within that.
        is_locked = getattr(segment, 'locked', False)

        # Trados-style coloured text badge (PM / CM) in place of the emoji icon.
        # The badge already conveys the match level, so we don't repeat the 101/102%.
        if status_def.badge_text:
            badge = QLabel(status_def.badge_text)
            badge.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignCenter)
            badge.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)
            badge.setStyleSheet(
                f"background-color:{status_def.badge_bg}; color:{status_def.badge_fg};"
                " border-radius:3px; padding:0px 4px; font-size:10px; font-weight:bold;"
            )
            badge.setProperty("status_tooltip", status_def.label)
            badge.installEventFilter(self)
            layout.addWidget(badge)
            if is_locked:
                lock_lbl = QLabel(self.tr('<span style="font-size:14px; line-height:1.25;">🔒</span>'))
                lock_lbl.setTextFormat(Qt.TextFormat.RichText)
                lock_lbl.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
                lock_lbl.setContentsMargins(0, 0, 0, 0)
                lock_lbl.setProperty("status_tooltip", "Locked")
                lock_lbl.installEventFilter(self)
                layout.addWidget(lock_lbl)
            if indicator_bg:
                widget.setStyleSheet(f"background: {indicator_bg};")
            layout.addStretch(1)
            return widget

        # Icon colour now comes from the status definition (icon_color) instead
        # of a hard-coded special case for "confirmed". Statuses whose glyph is
        # a colour emoji leave icon_color empty and draw in their own colours;
        # the two commonest statuses use monochrome Dingbats text glyphs
        # (✔ U+2714 / ✘ U+2718) precisely so they obey font-size and cannot be
        # clipped by the tight single-line row.
        icon_text = "🔒" if is_locked else status_def.icon
        icon_colour = "" if is_locked else (status_def.icon_color or "")
        colour_css = f"color:{icon_colour}; " if icon_colour else ""
        icon_html = f'<span style="{colour_css}font-size:14px; line-height:1.25;">{icon_text}</span>'

        status_label = QLabel(icon_html)
        status_label.setTextFormat(Qt.TextFormat.RichText)  # Enable HTML rendering
        status_label.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
        status_label.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Expanding)  # Expand vertically to match row height
        status_label.setContentsMargins(0, 0, 0, 0)  # No internal padding to prevent clipping in tight rows
        # Store tooltip text as property - we'll show it manually to avoid black tooltip bug
        status_label.setProperty("status_tooltip", status_def.label)
        status_label.installEventFilter(self)

        # Colour-code the comment background: amber (SC) / purple (PC) / split
        # (both). See _comment_indicator_bg. (issue #234 pt.1)
        if indicator_bg:
            status_label.setStyleSheet(f"padding: 2px 4px; background: {indicator_bg}; border-radius: 3px;")
        # Note: No stylesheet for non-notes case to avoid interfering with HTML color
        layout.addWidget(status_label)

        # Show match percentage if available, otherwise show the status short_label
        if segment.match_percent is not None:
            match_text = f"{segment.match_percent}%"
            match_label = QLabel(match_text)
            match_label.setAlignment(Qt.AlignmentFlag.AlignCenter)
            match_label.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)
            if segment.match_percent >= 101:
                match_label.setStyleSheet("color: #1b5e20; font-weight: bold; font-size: 11px; padding: 0px;")
                match_label.setProperty("status_tooltip", "Context match (101% or better)")
            elif segment.match_percent >= 100:
                match_label.setStyleSheet("color: #2e7d32; font-weight: bold; font-size: 11px; padding: 0px;")
                match_label.setProperty("status_tooltip", "Exact match (100%)")
            elif segment.match_percent >= 90:
                match_label.setStyleSheet("color: #1565C0; font-weight: bold; font-size: 11px; padding: 0px;")
                match_label.setProperty("status_tooltip", f"High fuzzy match {segment.match_percent}%")
            else:
                match_label.setStyleSheet("color: #0d47a1; font-size: 11px; padding: 0px;")
                match_label.setProperty("status_tooltip", f"Fuzzy match {segment.match_percent}%")
            match_label.installEventFilter(self)
            layout.addWidget(match_label)
        elif status_def.short_label:
            # No match %, show a short text abbreviation to the right of the icon (e.g. "CM", "MT", "Rep")
            short_lbl = QLabel(status_def.short_label)
            short_lbl.setAlignment(Qt.AlignmentFlag.AlignVCenter | Qt.AlignmentFlag.AlignLeft)
            short_lbl.setSizePolicy(QSizePolicy.Policy.Preferred, QSizePolicy.Policy.Preferred)
            short_lbl.setStyleSheet("color: #444; font-size: 10px; font-weight: bold; padding: 0px;")
            short_lbl.setProperty("status_tooltip", status_def.label)
            short_lbl.installEventFilter(self)
            layout.addWidget(short_lbl)

        layout.addStretch(1)

        return widget

    def _status_cell_comment_menu(self, widget, pos, comment_id, count):
        """Right-click menu on the Status column for a segment that has comments.

        Lets segment-level comments (no highlighted range in the cells) be
        opened straight from the status indicator.
        """
        from PyQt6.QtWidgets import QMenu
        from PyQt6.QtGui import QAction
        menu = QMenu(widget)
        label = "💬 Open comment" if count <= 1 else f"💬 Open comments ({count})"
        act = QAction(label, menu)
        act.triggered.connect(lambda: self._open_comment_in_panel(comment_id))
        menu.addAction(act)
        menu.exec(widget.mapToGlobal(pos))

    def _get_custom_tooltip(self):
        """Get or create the custom tooltip label widget."""
        if not hasattr(self, '_custom_tooltip') or self._custom_tooltip is None:
            self._custom_tooltip = QLabel()
            self._custom_tooltip.setWindowFlags(
                Qt.WindowType.ToolTip | Qt.WindowType.FramelessWindowHint
            )
            self._custom_tooltip.setStyleSheet("""
                QLabel {
                    background-color: #f5f5f5;
                    color: #333333;
                    border: 1px solid #d0d0d0;
                    padding: 4px 8px;
                    font-size: 12px;
                }
            """)
            self._custom_tooltip.hide()
        return self._custom_tooltip

    def eventFilter(self, obj, event):
        """Handle tooltip events for status labels using custom tooltip widget."""
        from PyQt6.QtCore import QEvent

        tooltip_text = obj.property("status_tooltip") if hasattr(obj, 'property') else None

        if tooltip_text:
            if event.type() == QEvent.Type.ToolTip:
                # Append the segment's comment summary (stored on the parent
                # status widget) so hovering the Status column reveals comments,
                # including segment-level ones that have no highlighted range.
                display_text = tooltip_text
                try:
                    parent = obj.parentWidget()
                    ctip = parent.property("comment_tooltip") if parent is not None else None
                    if ctip:
                        display_text = f"{tooltip_text}\n{ctip}"
                except Exception:
                    pass
                # Show our custom tooltip instead of Qt's
                tooltip = self._get_custom_tooltip()
                tooltip.setText(display_text)
                tooltip.adjustSize()
                # Position near the cursor
                pos = event.globalPos()
                tooltip.move(pos.x() + 10, pos.y() + 10)
                tooltip.show()
                return True  # Consume the event to prevent Qt's tooltip
            elif event.type() == QEvent.Type.Leave:
                # Hide custom tooltip when mouse leaves
                if hasattr(self, '_custom_tooltip') and self._custom_tooltip:
                    self._custom_tooltip.hide()

        return super().eventFilter(obj, event)

    def _update_status_cell(self, row: int, segment: Segment):
        status_widget = self._create_status_cell_widget(segment)
        self.table.setCellWidget(row, 4, status_widget)
        status_item = self.table.item(row, 4)
        if status_item is None:
            status_item = QTableWidgetItem()
            self.table.setItem(row, 4, status_item)
        status_item.setText("")
        status_item.setFlags(Qt.ItemFlag.ItemIsSelectable | Qt.ItemFlag.ItemIsEnabled)
        # Set background color on table item (widget is transparent)
        status_item.setBackground(QColor(get_status(segment.status).color))
        status_item.setData(Qt.ItemDataRole.DisplayRole, "")
        status_widget.updateGeometry()

    def _refresh_segment_status(self, segment: Segment):
        if not self.current_project:
            return
        updated_row = None
        for row, seg in enumerate(self.current_project.segments):
            if seg.id == segment.id:
                self._update_status_cell(row, seg)
                updated_row = row
                break

        # Update list view entry in place (if visible)
        if hasattr(self, 'list_tree') and self.list_tree:
            matches = self.list_tree.findItems(str(segment.id), Qt.MatchFlag.MatchExactly, 0)
            for item in matches:
                status_def = get_status(segment.status)
                match_text = f"{segment.match_percent}%" if segment.match_percent is not None else ""
                display = f"{status_def.icon}"
                if match_text:
                    display += f"  {match_text}"
                if segment.notes and segment.notes.strip():
                    display += "  💬"
                if getattr(segment, 'proofreading_notes', None):
                    display += "  ✅"
                item.setText(2, display)
                status_tooltip = status_def.label
                if segment.match_percent is not None:
                    status_tooltip += f" | {segment.match_percent}% match"
                if segment.notes and segment.notes.strip():
                    status_tooltip += f"\nSegment comment: {segment.notes.strip()}"
                if getattr(segment, 'proofreading_notes', None):
                    model_count = len(segment.proofreading_notes)
                    status_tooltip += f"\nProofreading comment: {model_count} LLM result{'s' if model_count != 1 else ''}"
                item.setToolTip(2, status_tooltip)
                item.setBackground(2, QColor(status_def.color))
                # Monochrome text-glyph icons carry their colour in the status
                # definition; without this the list view would draw the ✘/✔ in
                # plain black now that they are no longer colour emoji.
                if status_def.icon_color:
                    item.setForeground(2, QColor(status_def.icon_color))

        # Recalculate row height after status cell update to prevent layout corruption
        if updated_row is not None:
            self._auto_resize_single_row(updated_row)

    def _refresh_segment_status_by_id(self, segment_id: int):
        """Refresh the status display for a segment by its ID."""
        if not self.current_project:
            return
        segment = next((seg for seg in self.current_project.segments if seg.id == segment_id), None)
        if segment:
            self._refresh_segment_status(segment)

    def _enforce_status_row_heights(self):
        """No longer needed - status widgets now adapt to row height."""
        # This method is kept for backward compatibility but does nothing
        pass


    
    def clear_grid(self):
        """Clear all rows from grid"""
        self.table.setRowCount(0)

    def _sync_bottom_dock_menu(self):
        """Keep the 'Under-grid panel' radio items (Hide / Above / Below) in
        sync with the dock's current visibility and position. The TermLens vs
        QuickTrans choice is made via the dock's tab bar, not the menu."""
        if not hasattr(self, 'bottom_tabs') or not hasattr(self, 'underdock_hide_action'):
            return
        try:
            visible = self.bottom_tabs.isVisible()
        except Exception:
            return
        above = visible and getattr(self, 'tabs_above_grid', False)
        below = visible and not getattr(self, 'tabs_above_grid', False)
        # setChecked does not emit triggered(), so this won't recurse.
        self.underdock_above_action.setChecked(above)
        self.underdock_below_action.setChecked(below)
        self.underdock_hide_action.setChecked(not visible)

    def _on_bottom_tab_changed(self, _idx):
        """Tab switched in the under-grid dock: remember which tab the user
        prefers (unless we're restoring at startup)."""
        if not getattr(self, '_restoring_dock', False):
            self._save_bottom_dock_active_tab()

    def _save_bottom_dock_active_tab(self):
        if not hasattr(self, 'bottom_tabs'):
            return
        try:
            cur = self.bottom_tabs.currentWidget()
            name = 'quicktrans' if cur is getattr(self, 'quicktrans_panel', None) else 'termlens'
            s = self.load_general_settings()
            s['bottom_dock_active_tab'] = name
            self.save_general_settings(s)
        except Exception:
            pass

    def _on_match_top_tab_changed(self, _idx):
        """Match Panel top tab switched (TermLens / QuickTrans): remember the
        choice (unless we're restoring at startup)."""
        if getattr(self, '_restoring_dock', False):
            return
        try:
            cur = self.match_top_tabs.currentWidget()
            name = 'quicktrans' if cur is getattr(self, 'quicktrans_panel_match', None) else 'termlens'
            s = self.load_general_settings()
            s['match_top_active_tab'] = name
            self.save_general_settings(s)
        except Exception:
            pass

    def _update_file_boundary_labels(self):
        """Create/reposition floating filename banner labels at file boundaries in multi-file projects.

        Labels are parented to the table viewport so they scroll with the table automatically.
        Called after load_segments_to_grid(), auto_resize_rows(), and on scroll/resize.
        """
        # Clean up existing labels
        for lbl in getattr(self, '_file_boundary_labels', []):
            lbl.setParent(None)
            lbl.deleteLater()
        self._file_boundary_labels = []

        if not hasattr(self, 'table') or not self.table:
            return
        if not self.current_project or not getattr(self.current_project, 'is_multifile', False):
            return

        segments = self.current_project.segments
        viewport = self.table.viewport()
        viewport_width = viewport.width()

        # Only rows on screen get a banner: this runs on every scroll step, and
        # making a label for every file boundary in the project (300 files →
        # 300 labels per step) made scrolling and loading slow (issue #185).
        # The row just below the viewport is included, since its banner sits
        # above its top edge.
        first = self.table.rowAt(0)
        if first < 0:
            return
        last = self.table.rowAt(viewport.height() - 1)
        if last < 0:
            last = len(segments) - 1
        for row in range(max(first, 1), min(last + 2, len(segments))):
            segment = segments[row]
            prev_file_id = getattr(segments[row - 1], 'file_id', None)
            curr_file_id = getattr(segment, 'file_id', None)
            if curr_file_id is None or prev_file_id is None or curr_file_id == prev_file_id:
                continue
            if self.table.isRowHidden(row):
                continue  # Don't show banner when file is filtered out

            # Get the Y position of this row in the viewport
            rect = self.table.visualRect(self.table.model().index(row, 0))
            if rect.isNull() or rect.top() < 0:
                continue

            file_name = getattr(segment, 'file_name', '') or f"File {curr_file_id}"
            lbl = QLabel(f"  📄  {file_name}", viewport)
            lbl.setFixedHeight(20)
            lbl.setFixedWidth(viewport_width)
            lbl.move(0, rect.top() - 20)
            lbl.setStyleSheet(
                "QLabel {"
                "  background-color: #1a3a5c;"
                "  color: #e8f0fe;"
                "  font-size: 10px;"
                "  font-weight: bold;"
                "  padding-left: 8px;"
                "  border-bottom: 1px solid #2196F3;"
                "}"
            )
            lbl.show()
            lbl.raise_()
            self._file_boundary_labels.append(lbl)

    def auto_resize_rows(self):
        """Auto-resize all rows to fit content - Compact version"""
        if not hasattr(self, 'table') or not self.table:
            return

        # Reduce width slightly to account for padding and prevent text cut-off
        width_reduction = 8

        # Manually calculate and set row heights for compact display
        last_pump = time.monotonic()
        for row in range(self.table.rowCount()):
            # Keep UI responsive during large grid updates – a few times a
            # second is enough; pumping every 50 rows cost more than the
            # resizing itself on a 17,000-row project (issue #185).
            if time.monotonic() - last_pump > 0.1:
                QApplication.processEvents()
                last_pump = time.monotonic()
            self._auto_resize_single_row(row, width_reduction)

        self.log("✓ Auto-resized rows to fit content (compact)")
        self._enforce_status_row_heights()
        self._update_file_boundary_labels()
    
    def _auto_resize_single_row(self, row: int, width_reduction: int = 8):
        """Auto-resize a single row to fit its content. Called automatically after text changes."""
        if not hasattr(self, 'table') or not self.table:
            return
        if row < 0 or row >= self.table.rowCount():
            return

        # Minimum column width threshold - if columns are narrower than this,
        # layout isn't ready yet and we should skip resizing
        MIN_COL_WIDTH = 100

        max_height = 1

        # Check source cell (column 2)
        source_widget = self.table.cellWidget(row, 2)
        if source_widget and isinstance(source_widget, ReadOnlyGridTextEditor):
            doc = source_widget.document()
            if doc:
                col_width = self.table.columnWidth(2) - width_reduction
                if col_width >= MIN_COL_WIDTH:
                    doc.setTextWidth(col_width)
                    # Use documentLayout().documentSize() to force fresh calculation
                    layout = doc.documentLayout()
                    if layout:
                        size = layout.documentSize()
                        if size.isValid():
                            height = int(size.height())
                            max_height = max(max_height, height)

        # Check target cell (column 3)
        target_widget = self.table.cellWidget(row, 3)
        if target_widget and isinstance(target_widget, EditableGridTextEditor):
            doc = target_widget.document()
            if doc:
                col_width = self.table.columnWidth(3) - width_reduction
                if col_width >= MIN_COL_WIDTH:
                    doc.setTextWidth(col_width)
                    # Use documentLayout().documentSize() to force fresh calculation
                    layout = doc.documentLayout()
                    if layout:
                        size = layout.documentSize()
                        if size.isValid():
                            height = int(size.height())
                            max_height = max(max_height, height)
        
        # Set row height with minimal padding
        # Minimum 32px to accommodate status icons (16px) + match text + padding without any cutoff
        compact_height = max(max_height + 2, 32)

        # Add space for the file boundary banner (20px) at the BOTTOM of the last row of each file.
        # The banner floats above the NEXT row's top, so the space must come from this row's height.
        if (self.current_project and
                getattr(self.current_project, 'is_multifile', False)):
            segments = self.current_project.segments
            next_row = row + 1
            if next_row < len(segments):
                curr_file_id = getattr(segments[row], 'file_id', None)
                next_file_id = getattr(segments[next_row], 'file_id', None)
                if (curr_file_id is not None and next_file_id is not None
                        and curr_file_id != next_file_id):
                    compact_height += 20  # Banner sits in the extra space at the bottom of this row

        self.table.setRowHeight(row, compact_height)

    def _resize_visible_rows(self):
        """Resize only visible (non-hidden) rows for efficiency after pagination/filter changes."""
        if not hasattr(self, 'table') or not self.table:
            return
        row_count = self.table.rowCount()
        for row in range(row_count):
            if not self.table.isRowHidden(row):
                self._auto_resize_single_row(row)

    def _on_column_resized(self, logical_index: int, old_size: int, new_size: int):
        """Handle column resize - recalculate row heights for text reflow.

        Only reacts to Source (2) or Target (3) column changes since those
        contain wrapped text. Uses debouncing to avoid excessive recalculations
        during continuous dragging.
        """
        # Only care about Source or Target columns (they contain wrapped text)
        if logical_index not in (2, 3):
            return

        # Debounce: cancel previous timer and start a new one
        if hasattr(self, '_column_resize_timer') and self._column_resize_timer is not None:
            self._column_resize_timer.stop()

        self._column_resize_timer = QTimer()
        self._column_resize_timer.setSingleShot(True)
        self._column_resize_timer.timeout.connect(self._resize_visible_rows)
        self._column_resize_timer.start(150)  # 150ms debounce

    def apply_font_to_grid(self, skip_per_row: bool = False):
        """Apply selected font to all grid cells.

        Args:
            skip_per_row: When True, only the table-wide setup (table font,
                header font, segment-column width) runs; the per-row
                iteration that re-applies fonts to every QTextEdit and
                Type-column item is skipped. v1.10.148: used from
                load_segments_to_grid, where _populate_single_row has
                already set per-row fonts at construction time — re-doing
                that work added ~9 s on a 479-segment file.
        """
        font = QFont(self.default_font_family, self.default_font_size)

        # Re-setting an unchanged font still re-lays out every cell editor
        # (seconds on a big project, issue #185), so only set a real change.
        if self.table.font() != font:
            self.table.setFont(font)

        # Also update header font - same size as grid content, normal weight
        header_font = QFont(self.default_font_family, self.default_font_size, QFont.Weight.Normal)
        if self.table.horizontalHeader().font() != header_font:
            self.table.horizontalHeader().setFont(header_font)

        if skip_per_row:
            # Fast path for initial load: fonts on individual cells/widgets
            # were already set by _populate_single_row at construction time.
            self._update_segment_column_width()
            return

        # Type column (1) uses its own slightly smaller font – must match the
        # formula used at grid-creation time so zoom scales ¶ along with the text.
        # The ¶ paragraph mark gets an extra point shaved off (heavier glyph).
        type_font_para = QFont(self.default_font_family, max(6, self.default_font_size - 2))
        type_font_label = QFont(self.default_font_family, max(6, self.default_font_size - 1))

        # Update fonts in QTextEdit widgets (source and target columns)
        if hasattr(self, 'table') and self.table:
            for row in range(self.table.rowCount()):
                # Keep UI responsive during large grid updates
                if row % 50 == 0:
                    QApplication.processEvents()

                # Type column (1) - QTableWidgetItem with paragraph mark / heading label
                type_item = self.table.item(row, 1)
                if type_item is not None:
                    type_item.setFont(type_font_para if type_item.text() == "¶" else type_font_label)

                # Source column (2) - ReadOnlyGridTextEditor.
                # Use apply_grid_font_size (sets the size in the widget's own
                # stylesheet) – setFont alone loses to ThemeManager's app-level
                # `QTextEdit { font-size }` rule emitted at non-100% UI scale.
                source_widget = self.table.cellWidget(row, 2)
                if source_widget and isinstance(source_widget, ReadOnlyGridTextEditor):
                    source_widget.setFont(font)
                    source_widget.apply_grid_font_size(self.default_font_size)

                # Target column (3) - EditableGridTextEditor (same reason)
                target_widget = self.table.cellWidget(row, 3)
                if target_widget and isinstance(target_widget, EditableGridTextEditor):
                    target_widget.setFont(font)
                    target_widget.apply_grid_font_size(self.default_font_size)

        # Adjust segment number column width based on font size
        self._update_segment_column_width()
    
    def _update_segment_column_width(self):
        """Adjust segment number column width to fit the largest segment number.
        
        Uses font metrics to calculate exact width needed for the highest segment number.
        """
        if not hasattr(self, 'table') or not self.table:
            return
        
        # Get the highest segment number we need to display
        max_segment = self.table.rowCount()
        if max_segment == 0:
            max_segment = 1
        
        # Use font metrics to calculate exact width needed
        font = QFont(self.default_font_family, self.default_font_size)
        fm = QFontMetrics(font)
        
        # Measure the width of the largest number (as string)
        text_width = fm.horizontalAdvance(str(max_segment))
        
        # Add padding (8px on each side = 16px total)
        new_width = text_width + 16

        # Ensure minimum width for very small numbers
        new_width = max(30, new_width)

        self.table.setColumnWidth(0, new_width)
    
    def set_font_family(self, family_name: str):
        """Set font family from menu"""
        self.default_font_family = family_name
        self.apply_font_to_grid()
        self.auto_resize_rows()
        self.log(f"✓ Font changed to {family_name}")
    
    def increase_font_size(self):
        """Increase grid font size."""
        self.default_font_size = min(72, self.default_font_size + 1)
        self.apply_font_to_grid()
        self.auto_resize_rows()
        self.log(f"✓ Font size: {self.default_font_size}")
        # Save font size to preferences
        self.save_current_font_sizes()
    
    def decrease_font_size(self):
        """Decrease grid font size."""
        self.default_font_size = max(7, self.default_font_size - 1)
        self.apply_font_to_grid()
        self.auto_resize_rows()
        self.log(f"✓ Font size: {self.default_font_size}")
        # Save font size to preferences
        self.save_current_font_sizes()
    
    def refresh_grid_tag_colors(self):
        """Refresh tag highlight colors in all grid cells"""
        if not hasattr(self, 'table') or not self.table:
            return

        for row in range(self.table.rowCount()):
            # Keep UI responsive during large grid updates
            if row % 50 == 0:
                QApplication.processEvents()

            # Source column (2) - ReadOnlyGridTextEditor
            source_widget = self.table.cellWidget(row, 2)
            if source_widget and isinstance(source_widget, ReadOnlyGridTextEditor):
                if hasattr(source_widget, 'highlighter'):
                    source_widget.highlighter.set_tag_color(EditableGridTextEditor.tag_highlight_color)

            # Target column (3) - EditableGridTextEditor
            target_widget = self.table.cellWidget(row, 3)
            if target_widget and isinstance(target_widget, EditableGridTextEditor):
                if hasattr(target_widget, 'highlighter'):
                    target_widget.highlighter.set_tag_color(EditableGridTextEditor.tag_highlight_color)

    def _apply_row_color(self, row: int, source_widget, target_widget):
        """Apply alternating row color to source and target widgets for a specific row"""
        # Load settings (with caching to avoid repeated file reads)
        # Cache is keyed by theme name to refresh when theme changes
        theme = self.theme_manager.current_theme
        cache_key = f'_row_color_cache_{theme.name}'

        if not hasattr(self, cache_key):
            settings = self.load_general_settings()
            # Always use current theme colors for row alternation, not saved settings
            # This ensures rows are dark in dark themes and light in light themes
            cached_data = {
                'enabled': settings.get('enable_alternating_row_colors', True),
                'even_color': theme.base,  # Always use theme color
                'odd_color': theme.alternate_bg  # Always use theme color
            }
            setattr(self, cache_key, cached_data)
            # Also update the old cache name for backwards compatibility
            self._row_color_settings_cached = cached_data
        else:
            self._row_color_settings_cached = getattr(self, cache_key)
        
        settings = self._row_color_settings_cached
        
        if not settings['enabled']:
            # Use theme default colors when disabled - remove hardcoded backgrounds
            # The theme system will handle the background colors
            return
        
        # Check if this row is a locked segment (non-translatable, included for context)
        segment = None
        if (self.current_project and self.current_project.segments
                and 0 <= row < len(self.current_project.segments)):
            segment = self.current_project.segments[row]

        if segment and getattr(segment, 'locked', False):
            # Locked segments get a clearly distinct background across all themes
            is_dark = theme.name in ("Dark Blue", "Nord Dark")
            color = '#4a3a30' if is_dark else '#F0D9C8'
            row_color = QColor(color)
        else:
            # Normal: determine color based on row index (even/odd)
            color = settings['even_color'] if row % 2 == 0 else settings['odd_color']
            row_color = QColor(color)

        # Apply to ID column (column 0)
        id_item = self.table.item(row, 0)
        if id_item:
            id_item.setBackground(row_color)
        
        # Apply to Type column (column 1) - but preserve heading/list item colors
        type_item = self.table.item(row, 1)
        if type_item:
            type_text = type_item.text()
            # Only apply row color if it's not a special type (headings/list items have their own colors)
            if type_text not in ("H1", "H2", "H3", "H4", "Title", "li"):
                type_item.setBackground(row_color)
        
        # Apply to source widget
        if hasattr(source_widget, 'set_background_color'):
            source_widget.set_background_color(color)

        # Apply to target widget
        if hasattr(target_widget, 'set_background_color'):
            target_widget.set_background_color(color)

    # Selection tint colour for the source/target cell widgets in the current
    # row. Matches the QTableWidget::item:selected QSS rule so the tint is
    # consistent across columns 0/1 (table items) and 2/3 (cell widgets).
    # Pale Trados-style icy blue – clearly visible against alternating row
    # tints without overpowering the cell content (termbase pills, tag
    # markers, search highlights).
    SELECTION_TINT = "#CFE5F5"

    def _update_row_selection_tint(self, current_row, current_col, previous_row, previous_col):
        """Tint every column of the active row with the selection blue.

        QSS `::item:selected` is meant to handle this for free, but Qt paints
        explicit ``item.setBackground()`` brushes on top of the QSS colour –
        and we set those brushes via _apply_row_color for the ID/Type cells.
        That's why without this method the source/target widgets show the
        selection blue but the segment-number column stays on its alternating
        colour, breaking the visual unity of the active row.

        We walk every column so any cell widget that knows how to be tinted
        (``set_background_color``) gets the same shade, and any plain
        QTableWidgetItem gets its background brush overridden. The previous
        row is reverted to its alternating colour via the existing helper.
        """
        if not hasattr(self, 'table') or self.table is None:
            return

        column_count = self.table.columnCount()
        tint = QColor(self.SELECTION_TINT)

        # Restore alternating colour on the row we left.
        if previous_row is not None and previous_row >= 0 and previous_row != current_row:
            try:
                src_w = self.table.cellWidget(previous_row, 2)
                tgt_w = self.table.cellWidget(previous_row, 3)
                if src_w is not None or tgt_w is not None:
                    # _apply_row_color handles cols 0/1 (items) + 2/3 (widgets).
                    self._apply_row_color(previous_row, src_w, tgt_w)
            except RuntimeError:
                # Widget may have been deleted (e.g., during grid reload).
                pass

        # Tint the new current row across every column.
        if current_row is not None and current_row >= 0:
            try:
                for col in range(column_count):
                    widget = self.table.cellWidget(current_row, col)
                    if widget is not None:
                        # Cell widgets that opt into themed backgrounds
                        # (source/target QTextEdits) take the tint via their
                        # API. Other cell widgets are left alone – they have
                        # their own opinions about how to render selection.
                        if hasattr(widget, 'set_background_color'):
                            # Force dark text so the cell stays readable on the
                            # pale-blue selection tint (light editor text on light
                            # blue is unreadable in dark themes).
                            widget.set_background_color(self.SELECTION_TINT, text_color='#000000')
                    else:
                        item = self.table.item(current_row, col)
                        if item is not None:
                            item.setBackground(tint)
            except RuntimeError:
                pass

    def apply_alternating_row_colors(self):
        """Apply alternating row colors to all source and target cells in the grid"""
        if not hasattr(self, 'table') or not self.table:
            return

        # Clear cached settings to force reload
        if hasattr(self, '_row_color_settings_cached'):
            delattr(self, '_row_color_settings_cached')

        for row in range(self.table.rowCount()):
            # Keep UI responsive during large grid updates
            if row % 50 == 0:
                QApplication.processEvents()

            source_widget = self.table.cellWidget(row, 2)
            target_widget = self.table.cellWidget(row, 3)

            if source_widget and target_widget:
                self._apply_row_color(row, source_widget, target_widget)

        # Re-apply the selection tint to the current row across all columns –
        # we just overwrote its cells with the alternating colour. Pass
        # previous_row=-1 so the helper skips the restore branch.
        current_row = self.table.currentRow()
        if current_row is not None and current_row >= 0:
            self._update_row_selection_tint(current_row, 0, -1, 0)

        self.log("✓ Alternating row colors applied")
    
